window.KHO_DATA_L4_MITHUAT = [
{"lop":4,"mon":"Mĩ thuật","tuan":1,"tiet":1,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm tạo hình của chạm khắc đình làng qua ảnh phóng to.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu ảnh chụp mảng chạm khắc gỗ và tượng tròn ở đình làng lên máy chiếu, phóng to chi tiết hình rồng, người, hoa lá để HS thấy mảng nông sâu, nét đục chắc khoẻ; ảnh có chú thích tên đình, địa phương để HS nêu cảm nhận về “Vẻ đẹp trong điêu khắc đình làng Việt Nam”.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem thêm đoạn phim ngắn giới thiệu một ngôi đình trên tivi, ghi vào phiếu tên đình, nơi có đình, hình ảnh được chạm khắc và chất liệu gỗ; từ đó mỗi em chọn một hình ảnh muốn khai thác cho sản phẩm ở tiết sau và nói lí do chọn.\n⚠ (Miền 4: An toàn) Ảnh tư liệu di sản phải lấy từ trang của bảo tàng, cơ quan văn hoá hoặc sách đã xuất bản và ghi rõ nguồn khi đưa vào bài; không tải ảnh trôi nổi không rõ nơi chụp rồi chú thích sai tên di tích.","hs":"- HS nêu được đặc điểm tạo hình của chạm khắc gỗ, tượng tròn đình làng qua ảnh phóng to trên máy chiếu.\n- HS ghi được tên đình, hình ảnh chạm khắc từ phim tư liệu và chọn hình ảnh cho sản phẩm tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":2,"tiet":2,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nắm được thứ tự các bước làm sản phẩm nhờ tự tua chậm clip.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu ảnh từng bước thực hiện sản phẩm trong SGK Mĩ thuật 4 lên máy chiếu, phóng to bước phác hình, tạo mảng nổi bằng đất nặn hoặc bìa, tỉa chi tiết theo hoạ tiết chạm khắc đình làng; thao tác làm mẫu của GV được quay và chiếu lại chậm để HS nắm thứ tự các bước.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS lập bảng các bước làm sản phẩm của mình theo mẫu trên màn hình, ghi rõ hình ảnh chọn từ điêu khắc đình làng, chất liệu và bước em thấy khó; GV chụp ảnh bản phác nhanh của vài HS, chiếu lên để cả lớp góp ý bố cục trước khi thực hành ở tiết sau.\n⚠ (Miền 4: An toàn) Clip mở đúng đường dẫn GV cung cấp, không bấm sang các clip gợi ý bên cạnh; khi làm sản phẩm không dùng dao, đục sắc mà dùng que gỗ, bút hết mực để tạo nét trên đất nặn.","hs":"- HS nêu đúng thứ tự các bước thực hiện sản phẩm sau khi xem ảnh và đoạn quay chiếu chậm.\n- HS lập được bảng các bước, nêu bước khó và cách xử lí; góp ý bố cục cho bạn qua ảnh phác thảo."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":3,"tiet":3,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện vẻ đẹp tạo hình trong chạm khắc gỗ và tượng tròn ở đình làng theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về chạm khắc gỗ và tượng tròn ở đình làng để trình chiếu; hai sản phẩm mẫu, một sản phẩm đắp nổi và một sản phẩm tượng tròn để phân tích trực quan; bảng tiêu chí đánh giá viết to treo trước lớp; que nặn, tăm tre, bảng nặn, khăn lau.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là đất nặn để đắp nổi hoặc nặn hình khối 3D; vật liệu thay thế dễ kiếm: đất sét địa phương, bột mì trộn muối, giấy báo cũ vò chặt bọc hồ, bìa carton cắt lớp chồng nhau, vỏ hộp, lá cây khô, hột hạt, dây len, vải vụn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho các nhóm bày vật liệu và bản phác của tiết trước lên bàn, kiểm tra nhanh và bổ sung đất nặn cho HS còn thiếu.\n- GV tổ chức trò chơi Ai nhớ nhanh: chiếu 3 hình chạm khắc đình làng trong 10 giây rồi tắt và hỏi: Bức chạm khắc vừa rồi có những hình ảnh gì? Hình nào được chạm nổi rõ nhất?\n- GV hỏi tiếp: Chạm khắc gỗ và tượng tròn khác nhau ở điểm nào?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm về vẻ đẹp điêu khắc đình làng.","hs":"- HS bày vật liệu, bản phác và đồ dùng lên bàn theo nhóm, báo cáo phần còn thiếu.\n- HS quan sát và trả lời: có hình người đang múa, hình rồng, hình lá đề; hình người được chạm nổi cao nên rõ nhất.\n- HS trả lời: chạm khắc gỗ nổi trên một mặt phẳng, còn tượng tròn nhìn được từ mọi phía.\n- HS lắng nghe, nêu ý tưởng sản phẩm mình sẽ làm và sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại hai sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải thể hiện được nét đặc trưng của tạo hình đình làng là hình khối chắc khoẻ, mảng đơn giản, chi tiết mộc mạc.\n- GV lưu ý bố cục, màu sắc, chất liệu trước khi thực hành: hình chính đặt gần giữa và chiếm khoảng hai phần ba diện tích; các mảng phụ nhỏ hơn, không chia đều mà có chỗ thưa chỗ dày; màu nên dùng gam nâu, vàng đất, be gợi màu gỗ và thêm chút đậm nhạt cho hình nổi khối.\n- GV làm mẫu chậm ở bước khó là bước tạo độ nổi: cán một lớp đất mỏng làm nền, đắp thêm đất lên chỗ cần nổi cao, miết mép cho chuyển tiếp mềm, rồi dùng tăm tre vạch nét trang trí.\n- GV hỏi: Muốn hình người trong bức đắp nổi trông chắc khoẻ như chạm khắc đình làng thì em tạo hình thế nào? GV chốt và nhắc an toàn: không đưa đất nặn lên miệng, cắt bìa bằng kéo chứ không dùng dao rọc, rửa tay sau khi thực hành.","hs":"- HS quan sát hai sản phẩm mẫu, chỉ ra điểm khác nhau giữa đắp nổi và tượng tròn.\n- HS nhớ lại yêu cầu của chủ đề và hình dung sản phẩm mình sẽ làm, chọn chất liệu phù hợp.\n- HS theo dõi GV làm mẫu, nhắc lại kĩ thuật tạo độ nổi: cán nền, đắp thêm, miết mép, vạch nét.\n- HS trả lời: vẽ và nặn hình đơn giản, thân người mập chắc, tay chân to bản, ít chi tiết vụn.\n- HS nhắc lại quy định an toàn và vệ sinh khi thực hành."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 chọn hình ảnh muốn thể hiện (cảnh múa hát, đấu vật, chèo thuyền, rồng, lá đề); Bước 2 phác bố cục lên nền; Bước 3 tạo hình khối chính; Bước 4 đắp thêm chi tiết và vạch nét trang trí; Bước 5 tạo đậm nhạt bằng màu hoặc bằng độ nổi rồi đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng đất nặn, giấy màu, vật liệu tái sử dụng hợp lí, an toàn; nhóm thiếu đất nặn thì dùng giấy báo cũ vò chặt bọc hồ hoặc bìa carton cắt nhiều lớp chồng lên nhau để tạo độ nổi.\n- GV làm mẫu lại riêng cho HS còn lúng túng ở chỗ nối các khối: miết kĩ chỗ tiếp giáp, cắm tăm tre làm trụ cho chi tiết nhỏ khỏi rơi.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, lau bảng nặn, gom vật liệu thừa và rửa tay.","hs":"- HS thực hành theo 5 bước, làm hình khối chính trước rồi mới thêm chi tiết.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách sắp xếp bố cục và chọn chất liệu.\n- HS miết kĩ chỗ nối, dùng tăm tre làm trụ và vạch nét trang trí cho sản phẩm mộc mạc, chắc khoẻ.\n- HS đối chiếu sản phẩm với tiêu chí, chỉnh sửa chỗ chưa đạt rồi đặt tên sản phẩm.\n- HS hoàn thiện, lau bảng nặn, gom vật liệu thừa và rửa tay sạch."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini ở góc lớp: bảng nhóm Đắp nổi và bàn trưng bày Tượng tròn, mỗi sản phẩm có mẩu giấy ghi tên và tên sản phẩm.\n- GV nêu tiêu chí đánh giá: (1) có hình ảnh chính rõ, gợi được vẻ đẹp tạo hình đình làng; (2) bố cục cân đối, mảng chính phụ hợp lí; (3) màu sắc hài hoà, có đậm nhạt hoặc có độ nổi khối; (4) sản phẩm chắc chắn, sạch sẽ, có ý tưởng riêng.\n- GV cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí bằng cách ghi ba mức tốt, đạt, cần cố gắng vào phiếu; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm cần chỉnh.\n- GV cho HS đi xem phòng tranh, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS giữ sản phẩm ở góc lớp và chuẩn bị giấy vẽ, màu, giấy màu cho chủ đề tranh dân gian.","hs":"- HS đặt sản phẩm vào đúng khu trưng bày, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá trước khi nhận xét.\n- HS tự đánh giá sản phẩm của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì hình người đắp nổi cao nên nhìn rất chắc khoẻ.\n- HS nhắc lại điều đã học và ghi nhớ đồ dùng cần chuẩn bị cho tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":4,"tiet":4,"bai":"Chủ đề 1: Vẻ đẹp trong điêu khắc đình làng Việt Nam (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý, có ý thức giữ gìn di sản mĩ thuật của quê hương, đất nước.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.3 CB2a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS chụp và đưa được ảnh sản phẩm vào trang trưng bày kèm thông tin tác giả.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; đất nặn, giấy màu, vật liệu tái sử dụng để đắp nổi hoặc nặn hình khối 3D (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong điêu khắc đình làng việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS tự chụp sản phẩm của mình bằng thiết bị của lớp, chọn hướng sáng chếch để mảng chạm nổi rõ, rồi đưa ảnh vào trang trưng bày chung kèm tên tác giả và tên sản phẩm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS xem trang trưng bày và viết một lời nhận xét cho sản phẩm của bạn theo mẫu: một điều em thích và một điều em muốn hỏi thêm.\n⚠ (Miền 4: An toàn) Chỉ chụp sản phẩm, không chụp bạn khi bạn chưa đồng ý; nhận xét phải nêu cụ thể vào sản phẩm chứ không bình luận về người; trang trưng bày chỉ chia sẻ trong lớp và với cha mẹ.","hs":"- HS chụp và đưa được ảnh sản phẩm vào trang trưng bày kèm thông tin tác giả.\n- HS viết được lời nhận xét cụ thể, thiện chí cho sản phẩm của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 1, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":5,"tiet":5,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống).\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được cách diễn tả không gian riêng của tranh dân gian.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến một số dạng không gian trong tranh dân gian việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống).\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bộ sưu tập số tranh Đông Hồ, Hàng Trống trên trang của bảo tàng; HS phóng to từng bức để thấy tranh dân gian sắp xếp nhân vật to nhỏ theo vai trò chứ không theo xa gần, và nhận ra dòng chữ ghi tên dòng tranh dưới mỗi bức.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS so sánh một bức Đông Hồ với một bức Hàng Trống và ghi vào phiếu hai điểm khác nhau về màu và về nét.\n⚠ (Miền 4: An toàn) Tranh dân gian là di sản và mỗi bản chụp đều thuộc về nơi lưu giữ; khi dùng ảnh tranh vào bài của mình, HS ghi rõ tên tranh, dòng tranh và nơi cung cấp ảnh.","hs":"- HS nêu được cách diễn tả không gian riêng của tranh dân gian.\n- HS ghi được nguồn khi sử dụng ảnh tranh dân gian."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":6,"tiet":6,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống) thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về tranh Đông Hồ, Hàng Trống để trình chiếu; sản phẩm mẫu và một bản phác bố cục làm dở để phân tích trực quan; khuôn in tự tạo từ củ khoai, miếng xốp, lá cây để minh hoạ cách in đồ hoạ đơn giản; bảng tiêu chí đánh giá viết to.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu sáp hoặc màu goát và giấy vẽ; vật liệu thay thế dễ kiếm: bút dạ, phấn màu, mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, giấy màu xé dán thay cho tô màu, lá cây khô và vỏ hộp làm khuôn in.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, kiểm tra nhanh đồ dùng và cho HS thiếu màu mượn từ khay dự trữ của lớp.\n- GV tổ chức trò chơi Đoán tên tranh: chiếu lần lượt tranh Đám cưới chuột, Vinh hoa, Cá chép trông trăng và hỏi: Đây là tranh của dòng tranh nào? Nhân vật chính trong tranh được đặt ở đâu?\n- GV hỏi tiếp: Trong tranh dân gian, các nhân vật ở xa có bị vẽ nhỏ đi không?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: tìm hiểu cách thực hiện sản phẩm theo lối diễn tả không gian của tranh dân gian.","hs":"- HS bày đồ dùng lên bàn, báo cáo phần còn thiếu và nhận màu mượn.\n- HS quan sát và trả lời: Đám cưới chuột là tranh Đông Hồ, Vinh hoa là tranh Hàng Trống; nhân vật chính vẽ to và đặt ở giữa tranh.\n- HS trả lời: các nhân vật ở xa vẫn được vẽ to gần bằng nhau, chỉ xếp lên phía trên chứ không nhỏ dần.\n- HS lắng nghe, sẵn sàng vào bài học và mở SGK Mĩ thuật 4."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- (10 phút) GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4, khai thác cách diễn tả không gian và sắp xếp hình mảng của tranh dân gian: Bước 1 chọn đề tài và nhân vật chính; Bước 2 phác mảng chính to, đặt gần giữa tranh; Bước 3 phác các mảng phụ xếp theo lối tầng lớp, mảng ở xa đặt cao hơn nhưng vẫn giữ độ lớn tương đương; Bước 4 vẽ nét viền chắc khoẻ cho từng hình; Bước 5 tô màu theo mảng phẳng, ít pha trộn, rồi viền lại nét.\n- GV làm mẫu chậm hai bước khó là bước 3 và bước 5: xếp thử ba mảng giấy màu lên khổ giấy để HS thấy cách dồn mảng, sau đó tô một mảng phẳng đều và viền nét bằng bút dạ đen.\n- GV lưu ý kĩ thuật: nét viền đi một hơi, không tô đi tô lại; màu tô kín trong nét, không chồng quá hai lớp để giữ vẻ tươi phẳng của tranh dân gian; nếu in đồ hoạ thì chấm màu vừa phải, ấn thẳng, nhấc dứt khoát.\n- GV hỏi: Nếu em vẽ nhân vật phía sau nhỏ hẳn lại thì tranh còn giống tranh dân gian không? GV chốt sự khác nhau giữa không gian ước lệ của tranh dân gian và không gian xa gần; nhắc an toàn khi dùng kéo, keo, màu và giữ vệ sinh chỗ ngồi.","hs":"- HS quan sát, phân tích các bước thực hiện và chỉ vào hình minh hoạ tương ứng trong SGK.\n- HS nêu lại 5 bước theo đúng thứ tự và ghi nhớ vào vở.\n- HS theo dõi GV làm mẫu, một vài HS lên thao tác thử bước xếp mảng và bước viền nét.\n- HS trả lời: sẽ không còn giống tranh dân gian vì tranh dân gian giữ nhân vật to gần bằng nhau, chỉ xếp lên trên để chỉ khoảng cách.\n- HS nhắc lại lưu ý kĩ thuật và quy định an toàn, vệ sinh khi thực hành."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- (13 phút) GV cho HS phác nhanh ý tưởng và bố cục cho sản phẩm của mình trên giấy nháp hoặc mặt sau tờ lịch cũ, mỗi HS phác 2 phương án rồi chọn một phương án ưng ý nhất.\n- GV nêu yêu cầu của bản phác: có một mảng chính to đặt gần giữa, ít nhất hai mảng phụ xếp theo lối tầng lớp, ghi chú màu dự định dùng ở mỗi mảng.\n- GV quan sát, gợi ý điều chỉnh cho từng HS: mảng chính còn nhỏ thì phóng to lên, các mảng dính sát nhau thì tách ra cho thoáng, mảng phụ chia đều quá thì dồn lại cho có chỗ thưa chỗ dày.\n- GV nhắc HS chuẩn bị chất liệu phù hợp với phương án đã chọn và báo trước còn 2 phút để ghi tên, kẹp bản phác vào vở giữ cho phẳng.","hs":"- HS phác 2 phương án ý tưởng, so sánh rồi chọn một phương án ưng ý nhất để phát triển.\n- HS thể hiện rõ mảng chính, mảng phụ trên bản phác và ghi chú màu dự định dùng.\n- HS lựa chọn cách thể hiện và chuẩn bị chất liệu phù hợp: vẽ màu sáp, xé dán giấy màu hoặc in đồ hoạ đơn giản.\n- HS nghe góp ý của GV, chỉnh lại bố cục rồi ghi tên và kẹp bản phác vào vở."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV cho HS dán bản phác lên bảng nhóm theo chủ đề: bảng Tranh Đông Hồ và bảng Tranh Hàng Trống, tạo thành một góc trưng bày ý tưởng.\n- GV nêu tiêu chí nhận xét bản phác: (1) có mảng chính rõ, đúng đề tài đã chọn; (2) mảng phụ xếp theo lối tầng lớp kiểu tranh dân gian; (3) bố cục cân đối, có chỗ thưa chỗ dày; (4) bản phác sạch, nét gọn, có ý tưởng riêng.\n- GV cho HS tự đánh giá bản phác của mình theo 4 tiêu chí, sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào bản phác mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS chuẩn bị màu, giấy và vật liệu đã chọn cho tiết thực hành sau.","hs":"- HS dán bản phác lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản phác.\n- HS tự đánh giá bản phác của mình theo tiêu chí rồi đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn xếp đàn cá theo tầng lớp giống tranh dân gian.\n- HS nhắc lại điều đã học và ghi nhớ chất liệu cần chuẩn bị cho tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":7,"tiet":7,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện cách diễn tả không gian, sắp xếp hình mảng trong tranh dân gian (Đông Hồ, Hàng Trống) theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về tranh Đông Hồ, Hàng Trống để trình chiếu; sản phẩm mẫu đã hoàn thiện và một bài tô màu chưa đều để HS so sánh; khuôn in tự tạo từ củ khoai, miếng xốp, lá cây; bảng tiêu chí đánh giá viết to; phiếu tự đánh giá ba mức.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu sáp hoặc màu goát, giấy vẽ và bản phác của tiết trước; vật liệu thay thế dễ kiếm: bút dạ, phấn màu, mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, giấy màu xé dán, lá cây khô và vỏ hộp làm khuôn in.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác của tiết trước và màu lên bàn, kiểm tra nhanh và cho HS thiếu màu mượn từ khay dự trữ.\n- GV tổ chức trò chơi Ai nhanh hơn: chiếu hai bản bố cục, một bản mảng chính to rõ và một bản các mảng chia đều bằng nhau, rồi hỏi: Bản nào nhìn ra ngay nhân vật chính? Vì sao?\n- GV hỏi tiếp: Trong bản phác của em, đâu là mảng chính và em sẽ tô màu gì cho mảng ấy?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm theo bản phác đã chọn.","hs":"- HS đặt bản phác, màu và đồ dùng lên bàn, báo cáo phần còn thiếu.\n- HS quan sát và trả lời: bản thứ nhất rõ hơn vì mảng chính to và đặt gần giữa nên hút mắt người xem.\n- HS chỉ ra mảng chính trên bản phác của mình và nêu màu dự định dùng.\n- HS lắng nghe, sẵn sàng vào bài học và bày chất liệu đã chuẩn bị."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải thể hiện được lối diễn tả không gian ước lệ của tranh dân gian, hình mảng chắc khoẻ, nét viền rõ, màu tươi phẳng.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: giữ mảng chính to gần giữa; mảng phụ xếp theo tầng lớp; dùng 3 đến 4 màu chính, có một cặp đậm nhạt để hình chính nổi lên; nền nên để nhạt hoặc dùng màu điệp nhạt như tranh Đông Hồ.\n- GV làm mẫu chậm ở bước khó là tô mảng phẳng và viền nét: tô cùng một hướng nét, tô kín trong hình, chờ khô rồi viền nét đen một hơi bằng bút dạ hoặc que tăm chấm màu.\n- GV chiếu bài tô màu chưa đều và hỏi: Bài này chưa đẹp ở chỗ nào và sửa thế nào? GV chốt cách sửa; nhắc an toàn khi dùng kéo, keo và giữ vệ sinh, không vẩy màu sang bài bạn.","hs":"- HS quan sát sản phẩm mẫu, chỉ ra mảng chính, mảng phụ và cách xếp tầng lớp trên sản phẩm.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn dãy màu định dùng.\n- HS theo dõi GV làm mẫu, nhắc lại kĩ thuật tô mảng phẳng và viền nét một hơi.\n- HS trả lời: bài đó tô chồng nhiều lớp nên màu bị bẩn, nét viền đứt quãng; cần tô đều một lớp và viền lại nét cho liền.\n- HS nhắc lại quy định an toàn và vệ sinh khi thực hành."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 can hoặc vẽ lại bản phác lên giấy chính thức; Bước 2 vẽ nét viền các hình; Bước 3 tô màu mảng chính; Bước 4 tô mảng phụ và nền nhạt hơn; Bước 5 viền lại nét, thêm hoạ tiết nhỏ và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản hợp lí, an toàn; HS thiếu màu có thể xé dán giấy màu hoặc dùng bút dạ, phấn màu.\n- GV đi từng bàn, tô mẫu giúp một mảng nhỏ cho HS còn lúng túng; nhắc HS dùng màu goát phải chờ mảng cạnh khô mới tô tiếp để tránh loang.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, thấm khô bài, rửa cọ, đổ nước bẩn đúng nơi quy định và lau bàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách pha màu và cách giữ nét viền cho đều.\n- HS tô mảng chính trước, mảng phụ và nền sau, giữ màu tươi phẳng đúng tinh thần tranh dân gian.\n- HS đối chiếu bài với tiêu chí, viền lại nét, thêm hoạ tiết nhỏ và đặt tên sản phẩm.\n- HS hoàn thiện, thấm khô bài, rửa cọ, đổ nước bẩn đúng chỗ và lau sạch bàn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini ở góc lớp, treo sản phẩm lên dây bằng kẹp giấy và chia hai khu: khu Tranh Đông Hồ và khu Tranh Hàng Trống.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) có hình ảnh chính rõ, đúng đề tài; (2) hình mảng sắp xếp theo lối không gian ước lệ của tranh dân gian; (3) màu sắc tươi, hài hoà, có đậm nhạt làm nổi hình chính; (4) bài sạch sẽ, nét viền gọn, có ý tưởng riêng.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS giữ bài phẳng và chuẩn bị màu vẽ, giấy màu, vật liệu tạo tranh cho chủ đề Cảnh đẹp quê hương.","hs":"- HS treo sản phẩm vào đúng khu trưng bày, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì màu đỏ của mảng chính nổi hẳn lên trên nền nhạt.\n- HS nhắc lại điều đã học và ghi nhớ đồ dùng cần chuẩn bị cho chủ đề sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":8,"tiet":8,"bai":"Chủ đề 2: Một số dạng không gian trong tranh dân gian Việt Nam (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- trân trọng giá trị nghệ thuật truyền thống của dân tộc.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS viết được phần giới thiệu nêu rõ phần học hỏi và phần sáng tạo riêng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu sáp hoặc màu goát, giấy vẽ, giấy màu, in đồ hoạ đơn giản (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến một số dạng không gian trong tranh dân gian việt nam.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chụp sản phẩm và tự viết phần giới thiệu ba dòng: tên sản phẩm, em học được điều gì từ tranh dân gian, phần nào là ý riêng của em; GV ghép thành trang trưng bày của lớp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS trình bày sản phẩm trước nhóm, nghe bạn hỏi và trả lời được câu hỏi về cách mình sắp xếp hình mảng.\n⚠ (Miền 4: An toàn) Nếu bài của em mượn hình từ một bức tranh dân gian thì phải nói rõ mượn từ bức nào, không nhận cả bức tranh của người xưa là sáng tạo của mình; ảnh chỉ chia sẻ trong lớp.","hs":"- HS viết được phần giới thiệu nêu rõ phần học hỏi và phần sáng tạo riêng.\n- HS trả lời được câu hỏi của bạn về sản phẩm của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 2, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":9,"tiet":9,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra bố cục của cảnh nhờ xem địa danh từ nhiều góc nhìn.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS dùng bản đồ số và ảnh toàn cảnh để xem lại một địa danh ở quê mình từ trên cao và từ mặt đất, nhận ra bố cục của cảnh: đâu là mảng chính, đâu là nền; góc nhìn từ trên cao là góc mà đứng dưới đất không bao giờ thấy được.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một địa danh, thu thập hai đến ba ảnh và ghi lại nguồn từng ảnh vào phiếu tư liệu.\n⚠ (Miền 4: An toàn) Chỉ tra cứu trong ứng dụng bản đồ và trang tư liệu GV chỉ định; không nhập địa chỉ nhà mình, không đánh dấu vị trí cá nhân lên bản đồ; ảnh lấy về phải ghi nguồn.","hs":"- HS nhận ra bố cục của cảnh nhờ xem địa danh từ nhiều góc nhìn.\n- HS lập được phiếu tư liệu ảnh có ghi nguồn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":10,"tiet":10,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS xác định được mảng đậm nhạt của cảnh nhờ chuyển ảnh sang đen trắng.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS mở ảnh phong cảnh đã chọn trong phần mềm xem ảnh và chuyển ảnh sang chế độ đen trắng để nhìn rõ các mảng đậm nhạt đang bị màu sắc che lấp, nhờ đó xác định được đâu là mảng đậm nhất, đâu là mảng sáng nhất trước khi phác bố cục.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS phác bố cục mảng đậm nhạt trên giấy dựa vào ảnh đen trắng rồi mới chuyển sang vẽ màu.\n⚠ (Miền 4: An toàn) HS thao tác trên máy dùng chung của lớp, mở đúng thư mục ảnh của mình, không mở và không xoá tệp của bạn; chỉnh xong không lưu đè lên tệp ảnh gốc.","hs":"- HS xác định được mảng đậm nhạt của cảnh nhờ chuyển ảnh sang đen trắng.\n- HS phác được bố cục đậm nhạt trước khi vẽ màu."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":11,"tiet":11,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện hình, mảng, đậm nhạt và màu sắc để thể hiện cảnh đẹp quê hương theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về cảnh đẹp quê hương để trình chiếu; sản phẩm mẫu và một tranh phong cảnh vẽ đều một sắc độ để so sánh với tranh có đậm nhạt; thang đậm nhạt 3 bậc vẽ sẵn treo trước lớp; bảng tiêu chí đánh giá; phiếu tự đánh giá ba mức.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy vẽ, giấy màu và vật liệu tạo tranh; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, vỏ hộp, lá cây khô dán làm tán cây, hột hạt, dây len, vải vụn làm mảng ruộng và dòng sông.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác của tiết trước và vật liệu lên bàn, kiểm tra nhanh và bổ sung cho HS còn thiếu.\n- GV tổ chức trò chơi Kể tên cảnh đẹp: mỗi tổ kể nhanh một cảnh đẹp ở quê mình trong 1 phút, sau đó GV hỏi: Cảnh ấy đẹp nhất ở điểm nào?\n- GV chiếu hai tranh phong cảnh, một tranh tô đều một sắc độ và một tranh có đậm nhạt, rồi hỏi: Tranh nào có chiều sâu hơn? Vì sao?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm về cảnh đẹp quê hương.","hs":"- HS đặt bản phác, màu và vật liệu lên bàn, báo cáo phần còn thiếu.\n- HS các tổ kể tên cảnh đẹp quê mình và nêu điểm ấn tượng nhất của cảnh ấy.\n- HS quan sát và trả lời: tranh có đậm nhạt sâu hơn vì mảng gần đậm, mảng xa nhạt nên thấy được lớp trước lớp sau.\n- HS lắng nghe, nêu cảnh mình sẽ thể hiện và sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải dùng được hình, mảng, đậm nhạt và màu sắc để làm nổi vẻ đẹp của cảnh quê hương.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: chia tranh thành ba lớp cảnh gần, giữa, xa; lớp gần vẽ to, đậm, nhiều chi tiết; lớp xa vẽ nhỏ, nhạt, ít chi tiết; mảng chính đặt lệch khỏi chính giữa một chút cho tranh sinh động.\n- GV chỉ vào thang đậm nhạt 3 bậc và làm mẫu chậm cách tạo đậm nhạt: cùng một màu xanh, tô một lớp cho lớp cảnh xa, hai lớp cho lớp giữa, ba lớp cho lớp gần; nếu xé dán thì chọn giấy màu đậm dần về phía trước.\n- GV hỏi: Nếu cả ba lớp cảnh cùng một độ đậm thì tranh sẽ ra sao? GV chốt và nhắc an toàn khi dùng kéo, keo, màu; nhắc HS lót giấy báo dưới bàn trước khi tô màu.","hs":"- HS quan sát sản phẩm mẫu, chỉ ra ba lớp cảnh và mảng chính trên sản phẩm.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn chất liệu phù hợp.\n- HS theo dõi GV làm mẫu, nhắc lại cách tạo đậm nhạt bằng tô chồng lớp hoặc chọn giấy màu đậm dần.\n- HS trả lời: tranh sẽ bẹt, các lớp cảnh dính vào nhau, không thấy được chiều sâu.\n- HS nhắc lại quy định an toàn, vệ sinh và lót giấy báo dưới chỗ ngồi."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 vẽ lại bố cục đã phác lên giấy chính thức; Bước 2 vẽ hoặc cắt dán các mảng lớn của ba lớp cảnh; Bước 3 tô màu lớp xa trước, lớp gần sau; Bước 4 tạo đậm nhạt và thêm chi tiết cho lớp cảnh gần; Bước 5 hoàn thiện, viền nét chỗ cần rõ và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh hợp lí, an toàn; HS thiếu màu có thể xé dán giấy màu, dán lá cây khô làm tán cây, dùng vải vụn làm mảng ruộng.\n- GV đi từng bàn hỗ trợ, tô mẫu giúp một mảng nhỏ cho HS còn lúng túng, nhắc HS chờ mảng cạnh khô mới tô tiếp để tránh loang màu.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa và lau bàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách chia lớp cảnh và cách pha màu.\n- HS tô hoặc dán từ lớp cảnh xa đến lớp cảnh gần, tạo đậm nhạt rõ giữa các lớp.\n- HS đối chiếu bài với tiêu chí, thêm chi tiết cho lớp gần rồi đặt tên sản phẩm.\n- HS hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa và lau sạch bàn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini ở góc lớp, chia bảng nhóm theo chủ đề: bảng Cảnh làng quê, bảng Cảnh sông nước, bảng Cảnh phố phường.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) có hình ảnh chính rõ, đúng cảnh đẹp đã chọn; (2) bố cục cân đối, thấy rõ ba lớp cảnh; (3) màu sắc hài hoà, có đậm nhạt tạo chiều sâu; (4) bài sạch sẽ, hoàn chỉnh, có ý tưởng riêng.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào bài mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS giữ bài phẳng và chuẩn bị màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có cho chủ đề Vẻ đẹp trong cuộc sống.","hs":"- HS dán sản phẩm lên bảng nhóm đúng chủ đề, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì hàng cây phía xa tô nhạt làm cánh đồng trông rộng hẳn ra.\n- HS nhắc lại điều đã học và ghi nhớ đồ dùng cần chuẩn bị cho chủ đề sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":12,"tiet":12,"bai":"Chủ đề 3: Cảnh đẹp quê hương (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, tự hào về cảnh đẹp nơi mình sinh sống.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.2 CB2a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS tham gia sắp xếp và hoàn thiện trang triển lãm của lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, kéo, keo dán, vật liệu tạo tranh (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến cảnh đẹp quê hương.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp lập một trang triển lãm Cảnh đẹp quê hương gồm tranh của HS, mỗi tranh kèm tên địa danh và một câu giới thiệu; HS tự sắp xếp thứ tự tranh theo vùng để người xem dễ theo dõi.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS nhận xét tranh của bạn tập trung vào bố cục và cách dùng đậm nhạt, nói theo hướng góp ý chứ không phê phán.\n⚠ (Miền 4: An toàn) Tranh của ai thì ghi tên người ấy; ảnh chụp địa danh dùng làm tư liệu phải ghi nguồn ở cuối trang; trang triển lãm chia sẻ trong trường, muốn đưa lên trang của trường phải xin phép GV và cha mẹ.","hs":"- HS tham gia sắp xếp và hoàn thiện trang triển lãm của lớp.\n- HS nhận xét được tranh của bạn về bố cục và đậm nhạt."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 3, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":13,"tiet":13,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS mô tả được dáng và biểu cảm của người lao động qua ảnh tư liệu.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu loạt ảnh chụp người lao động đang làm việc: bác nông dân, cô lao công, chú thợ xây, người bán hàng; ảnh bắt đúng khoảnh khắc động cho HS thấy dáng người và biểu cảm mà quan sát thoáng qua ngoài đời không kịp ghi nhớ.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một ảnh, mô tả dáng người và đoán người trong ảnh đang nghĩ gì, cảm thấy thế nào.\n⚠ (Miền 4: An toàn) Ảnh chụp người lao động do GV lấy từ nguồn tư liệu có ghi tác giả; HS không chụp trộm người đang làm việc ngoài đường để lấy tư liệu, muốn chụp phải xin phép người ấy trước.","hs":"- HS mô tả được dáng và biểu cảm của người lao động qua ảnh tư liệu.\n- HS nêu được vì sao phải xin phép trước khi chụp ảnh người khác."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":14,"tiet":14,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về con người, đồ vật, hoạt động quen thuộc trong cuộc sống để trình chiếu; sản phẩm mẫu và một bản phác bố cục làm dở để phân tích trực quan; hình minh hoạ các bước vẽ dáng người bằng nét que; bảng tiêu chí đánh giá viết to.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy vẽ, đất nặn và vật liệu sẵn có; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, vỏ hộp, nắp chai, dây len làm tóc, vải vụn làm trang phục, hột hạt để đắp chi tiết.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, kiểm tra nhanh đồ dùng và vật liệu, bổ sung cho HS còn thiếu từ khay dự trữ của lớp.\n- GV tổ chức trò chơi Đoán hoạt động: mời 3 HS lần lượt làm động tác không lời (bán hàng, tưới cây, đá cầu) cho cả lớp đoán và hỏi: Nhờ chi tiết nào mà em đoán ra?\n- GV hỏi tiếp: Quanh em, hoạt động quen thuộc nào khiến em thấy đẹp và muốn thể hiện thành sản phẩm mĩ thuật?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: tìm hiểu cách thực hiện sản phẩm về vẻ đẹp trong cuộc sống.","hs":"- HS bày đồ dùng, vật liệu lên bàn và báo cáo phần còn thiếu.\n- 3 HS lên làm động tác không lời, cả lớp đoán và giải thích nhờ tư thế tay, chân, lưng mà nhận ra.\n- HS nêu ý tưởng của mình: bà ngồi têm trầu, mẹ gánh hàng ra chợ, các bạn chơi nhảy dây ở sân trường.\n- HS lắng nghe, sẵn sàng vào bài học và mở SGK Mĩ thuật 4."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- (10 phút) GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4, khai thác vẻ đẹp của con người, đồ vật, hoạt động quen thuộc: Bước 1 chọn một khoảnh khắc cụ thể để thể hiện; Bước 2 phác mảng chính là nhân vật đang hoạt động, đặt to và lệch nhẹ khỏi chính giữa; Bước 3 phác mảng phụ là đồ vật, bối cảnh xung quanh; Bước 4 vẽ chi tiết dáng người, đồ vật; Bước 5 thể hiện màu và đậm nhạt để nhân vật chính nổi lên.\n- GV làm mẫu chậm ở bước khó là bước 4: vẽ ba dáng người bằng nét que (dáng đứng gánh hàng, dáng ngồi bó gối, dáng cúi tưới cây), sau đó bọc khối cho nét que và thêm trang phục; mời 2 HS lên thao tác thử một dáng.\n- GV lưu ý kĩ thuật: dáng sinh động thì lưng hơi cong, tay chân gấp khúc, trọng tâm dồn về một chân; đồ vật vẽ theo khối cơ bản trước rồi mới thêm chi tiết; nếu nặn thì làm khối thân trước, gắn đầu và tay chân sau, miết kĩ chỗ nối.\n- GV hỏi: Vẽ thêm gì để người xem biết ngay nhân vật đang bán hàng? GV chốt và nhắc an toàn khi dùng kéo, keo, đất nặn; rửa tay sau khi thực hành.","hs":"- HS quan sát, phân tích các bước thực hiện và chỉ vào hình minh hoạ tương ứng trong SGK.\n- HS nêu lại 5 bước theo đúng thứ tự và ghi nhớ vào vở.\n- HS theo dõi GV làm mẫu, vẽ thử hai dáng người bằng nét que ra giấy nháp; 2 HS lên thao tác trước lớp.\n- HS trả lời: vẽ thêm quang gánh, rổ rau, cân, chiếc nón và vài người mua đứng quanh.\n- HS nhắc lại lưu ý kĩ thuật về dáng người và quy định an toàn, vệ sinh."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- (13 phút) GV cho HS phác nhanh ý tưởng và bố cục cho sản phẩm của mình trên giấy nháp, mỗi HS phác 2 phương án rồi chọn một phương án ưng ý nhất để phát triển.\n- GV nêu yêu cầu của bản phác: có ít nhất một nhân vật đang hoạt động làm mảng chính, hai mảng phụ về đồ vật hoặc bối cảnh, ghi chú chất liệu và màu dự định dùng.\n- GV quan sát, gợi ý điều chỉnh cho từng HS: nhân vật còn nhỏ thì phóng to lên, dáng còn cứng thì cho nghiêng người và gấp khuỷu tay, các mảng dính nhau thì tách ra cho thoáng.\n- GV nhắc HS chọn chất liệu vừa sức: vẽ màu, xé dán giấy màu hay nặn khối 3D; báo trước còn 2 phút để ghi tên và kẹp bản phác vào vở giữ phẳng.","hs":"- HS phác 2 phương án ý tưởng, so sánh rồi chọn một phương án ưng ý nhất.\n- HS thể hiện rõ mảng chính là nhân vật đang hoạt động và các mảng phụ trên bản phác.\n- HS lựa chọn cách thể hiện, ghi chú chất liệu và màu dự định dùng cho từng mảng.\n- HS nghe góp ý của GV, chỉnh dáng nhân vật cho sinh động rồi ghi tên và kẹp bản phác vào vở."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV cho HS dán bản phác lên bảng nhóm theo chủ đề: bảng Người thân của em, bảng Công việc quanh em, bảng Trò chơi của chúng em.\n- GV nêu tiêu chí nhận xét bản phác: (1) có mảng chính là nhân vật đang hoạt động, rõ nội dung; (2) bố cục cân đối, có chỗ thưa chỗ dày; (3) dáng người sinh động, đúng hoạt động; (4) bản phác sạch, nét gọn, có ý tưởng riêng.\n- GV cho HS tự đánh giá bản phác của mình theo 4 tiêu chí, sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào bản phác mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS chuẩn bị màu vẽ, giấy vẽ, đất nặn và vật liệu đã chọn cho tiết thực hành sau.","hs":"- HS dán bản phác lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản phác.\n- HS tự đánh giá bản phác của mình theo tiêu chí rồi đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì dáng bà ngồi têm trầu trông rất thật.\n- HS nhắc lại điều đã học và ghi nhớ chất liệu cần chuẩn bị cho tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":15,"tiet":15,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện vẻ đẹp của con người, đồ vật, hoạt động quen thuộc trong cuộc sống theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về con người, đồ vật, hoạt động quen thuộc trong cuộc sống để trình chiếu; sản phẩm mẫu và một bài tô màu chưa có đậm nhạt để HS so sánh; bảng tiêu chí đánh giá viết to; phiếu tự đánh giá ba mức; bảng nặn, khăn lau.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có và bản phác của tiết trước; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, vỏ hộp, nắp chai, dây len, vải vụn, hột hạt.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác của tiết trước, màu và vật liệu lên bàn, kiểm tra nhanh và bổ sung cho HS còn thiếu.\n- GV chiếu hai bài cùng một hình, một bài tô đều một sắc độ và một bài có đậm nhạt, rồi hỏi: Bài nào nhìn ra nhân vật chính nhanh hơn? Vì sao?\n- GV hỏi tiếp: Trong bản phác của em, nhân vật chính đang làm gì và em định tô màu gì cho nhân vật ấy?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm theo bản phác đã chọn.","hs":"- HS đặt bản phác, màu và vật liệu lên bàn, báo cáo phần còn thiếu.\n- HS quan sát và trả lời: bài có đậm nhạt rõ hơn vì nhân vật được tô đậm còn nền tô nhạt nên nổi lên.\n- HS nêu nội dung bản phác của mình và màu dự định dùng cho nhân vật chính.\n- HS lắng nghe, sẵn sàng vào bài học và bày chất liệu đã chuẩn bị."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải làm nổi được vẻ đẹp bình dị của con người, đồ vật, hoạt động quen thuộc bằng hình, mảng, màu sắc và đậm nhạt.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: nhân vật chính to, đặt lệch nhẹ khỏi chính giữa; đồ vật và bối cảnh nhỏ hơn; dùng 3 đến 4 màu chính, nền tô nhạt để nhân vật nổi lên; nếu nặn thì làm khối thân trước rồi mới gắn chi tiết.\n- GV làm mẫu chậm ở bước khó là tạo đậm nhạt trên nhân vật: tô một lớp màu nền cho toàn hình, sau đó tô chồng thêm 2 lớp ở phía khuất sáng và để nhạt ở phía có ánh sáng, cuối cùng viền nét cho hình gọn.\n- GV hỏi: Nếu nền và áo nhân vật cùng một màu đậm thì bài sẽ ra sao? GV chốt cách tránh; nhắc an toàn khi dùng kéo, keo, đất nặn và giữ vệ sinh chỗ ngồi.","hs":"- HS quan sát sản phẩm mẫu, chỉ ra nhân vật chính, mảng phụ và chỗ đậm chỗ nhạt.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn dãy màu định dùng.\n- HS theo dõi GV làm mẫu, nhắc lại cách tạo đậm nhạt bằng tô chồng lớp và cách viền nét.\n- HS trả lời: nhân vật sẽ lẫn vào nền nên phải đổi màu áo hoặc tô nền nhạt đi.\n- HS nhắc lại quy định an toàn và vệ sinh khi thực hành."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 chuyển bố cục đã phác lên giấy hoặc lên nền sản phẩm; Bước 2 dựng hình nhân vật chính; Bước 3 làm đồ vật, bối cảnh; Bước 4 thể hiện màu và đậm nhạt; Bước 5 hoàn thiện chi tiết, viền nét và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có hợp lí, an toàn; HS thiếu màu có thể xé dán giấy màu, dùng dây len làm tóc, vải vụn làm trang phục, nắp chai làm đồ vật.\n- GV đi từng bàn hỗ trợ: chỉnh lại dáng cho HS vẽ nhân vật còn cứng, làm mẫu lại chỗ nối khối cho HS nặn; nhắc HS chờ mảng cạnh khô mới tô tiếp để tránh loang màu.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa, lau bàn và rửa tay.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách dựng dáng người và cách phối màu.\n- HS thể hiện đậm nhạt để nhân vật chính nổi lên, thêm chi tiết cho bối cảnh sinh động.\n- HS đối chiếu bài với tiêu chí, chỉnh sửa chỗ chưa đạt rồi đặt tên sản phẩm.\n- HS hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa, lau bàn và rửa tay."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini ở góc lớp, chia bảng nhóm theo chủ đề: bảng Người thân của em, bảng Công việc quanh em, bảng Trò chơi của chúng em; sản phẩm 3D đặt trên bàn kê phía dưới.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) có hình ảnh chính rõ, thể hiện được một hoạt động quen thuộc; (2) bố cục cân đối, hình chính nổi bật; (3) màu sắc hài hoà, có đậm nhạt làm rõ nội dung; (4) sản phẩm sạch sẽ, hoàn chỉnh, có ý tưởng riêng.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS giữ sản phẩm và chuẩn bị giấy vẽ, màu vẽ, chất liệu quen dùng cho tiết kiểm tra cuối học kì I.","hs":"- HS đặt sản phẩm vào đúng khu trưng bày, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn tô nền nhạt nên dáng mẹ gánh hàng nổi hẳn lên.\n- HS nhắc lại điều đã học và ghi nhớ đồ dùng cần chuẩn bị cho tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":16,"tiet":16,"bai":"Chủ đề 4: Vẻ đẹp trong cuộc sống (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- biết trân trọng vẻ đẹp bình dị quanh mình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS đặt được tên và viết được câu nêu thông điệp cho tác phẩm của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu sẵn có (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến vẻ đẹp trong cuộc sống.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chụp sản phẩm, tự đặt tên cho tác phẩm của mình và viết một câu nói rõ mình muốn người xem cảm nhận điều gì; GV ghép thành trang trưng bày của lớp.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS xem trang trưng bày và đoán thông điệp trong tác phẩm của bạn, sau đó nghe bạn nói lại để biết mình đoán có đúng không.\n⚠ (Miền 4: An toàn) Tác phẩm vẽ về một người lao động cụ thể thì chỉ ghi nghề nghiệp, không ghi họ tên và nơi làm việc của người ấy; ảnh sản phẩm chia sẻ trong lớp.","hs":"- HS đặt được tên và viết được câu nêu thông điệp cho tác phẩm của mình.\n- HS đọc được thông điệp trong tác phẩm của bạn và trao đổi lại."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 4, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":17,"tiet":17,"bai":"Kiểm tra, đánh giá cuối học kì I","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong học kì để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình (hình, mảng, màu sắc, đậm nhạt) phù hợp nội dung.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.\n4. Tích hợp\n- Năng lực số 5.2 CB2b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS tự sắp xếp và đánh giá được các sản phẩm của mình trong học kì.","dodung":"- GV: đề kiểm tra hoặc yêu cầu thực hành, bảng tiêu chí đánh giá viết to treo trước lớp; bảng hệ thống bốn chủ đề đã học trong học kì I; phiếu tự đánh giá ba mức tốt, đạt, cần cố gắng; sao giấy để HS bình chọn; máy tính có thư mục ảnh sản phẩm của HS; thiết bị trình chiếu học liệu số.\n- HS: đồ dùng học tập môn Mĩ thuật, giấy vẽ, màu vẽ, chất liệu đã chuẩn bị. Vật liệu thay thế dễ kiếm khi thiếu đồ dùng: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, giấy màu, vỏ hộp, lá cây khô, hột hạt, dây len, vải vụn, đất sét địa phương.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, nêu mục đích tiết kiểm tra cuối học kì I: đánh giá sự tiến bộ của mỗi HS qua một sản phẩm mĩ thuật hoàn chỉnh chứ không so sánh HS này với HS khác.\n- GV cùng HS nhắc lại nhanh bốn chủ đề đã học bằng sơ đồ nhánh trên bảng và hỏi: Chủ đề nào em thấy mình làm tốt nhất? Em học được kĩ năng gì từ chủ đề đó?\n- GV công bố yêu cầu và tiêu chí đánh giá sản phẩm, treo bảng tiêu chí trước lớp cho HS đọc.\n- GV nhắc HS chọn nội dung và chất liệu vừa sức để làm kịp trong tiết học, nhắc an toàn khi dùng kéo, keo, màu.","hs":"- HS lắng nghe, nắm yêu cầu và tiêu chí; đọc lại bảng tiêu chí treo trước lớp.\n- HS nhắc lại tên bốn chủ đề đã học và kĩ năng chính của từng chủ đề.\n- HS trả lời: em làm tốt nhất chủ đề Cảnh đẹp quê hương vì em đã biết tạo đậm nhạt cho ba lớp cảnh.\n- HS hỏi lại chỗ chưa rõ trong yêu cầu và chuẩn bị đồ dùng, chất liệu lên bàn."},{"ten":"2. Thực hành kiểm tra","gv":"- (17 phút) GV tổ chức cho HS làm bài thực hành: mỗi HS tạo một sản phẩm mĩ thuật theo một chủ đề đã học trong học kì, làm theo trình tự Bước 1 chọn nội dung và chất liệu; Bước 2 phác bố cục, xác định mảng chính; Bước 3 dựng hình chi tiết; Bước 4 thể hiện màu và đậm nhạt; Bước 5 hoàn thiện, đặt tên và ghi tên mình.\n- GV bao quát lớp, hỗ trợ khi cần nhưng không làm thay, bảo đảm HS làm bài độc lập; nhắc HS bám bốn tiêu chí đã công bố.\n- GV gợi ý cho HS thiếu chất liệu: dùng mặt sau tờ lịch cũ thay giấy vẽ, xé dán giấy màu hoặc dán lá cây khô, hột hạt thay cho tô màu.\n- GV báo trước còn 3 phút để hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa và lau bàn.","hs":"- HS thực hành tạo sản phẩm theo yêu cầu, làm lần lượt 5 bước đã nêu.\n- HS vận dụng kiến thức, kĩ năng đã học về hình, mảng, màu sắc, đậm nhạt vào bài của mình.\n- HS làm bài độc lập, tự giải quyết khó khăn trước khi nhờ GV hỗ trợ.\n- HS đối chiếu bài với tiêu chí, chỉnh sửa rồi đặt tên sản phẩm và ghi tên mình.\n- HS hoàn thiện, thấm khô bài, gom vật liệu thừa và lau sạch bàn."},{"ten":"3. Trưng bày, đánh giá","gv":"- (7 phút) GV tổ chức cho HS trưng bày thành phòng tranh mini cuối học kì ở góc lớp, chia bảng nhóm theo bốn chủ đề đã học; sản phẩm 3D đặt trên bàn kê phía dưới.\n- GV nêu lại tiêu chí đánh giá: (1) có hình ảnh chính rõ, đúng chủ đề đã chọn; (2) bố cục cân đối, mảng chính phụ hợp lí; (3) màu sắc hài hoà, có đậm nhạt làm rõ nội dung; (4) sản phẩm hoàn chỉnh, sạch sẽ, có ý tưởng riêng.\n- GV phát phiếu cho HS tự đánh giá theo ba mức tốt, đạt, cần cố gắng; sau đó cho HS đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì... GV nhận xét, đánh giá theo tiêu chí và ghi nhận sự tiến bộ của từng HS.","hs":"- HS trưng bày sản phẩm vào đúng khu, giới thiệu ngắn về tên sản phẩm, nội dung và chất liệu đã dùng.\n- HS tự đánh giá sản phẩm của mình vào phiếu theo bốn tiêu chí ở ba mức.\n- HS đổi bài trong nhóm, nhận xét sản phẩm của bạn, nêu một điểm mạnh và một điểm nên chỉnh.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn dùng đậm nhạt rất khéo nên hình chính nổi hẳn lên."},{"ten":"4. Vận dụng - Dặn dò","gv":"- (4 phút) GV tổng kết tiết kiểm tra, nêu tên những HS có tiến bộ rõ rệt so với đầu học kì và tuyên dương cả lớp về tinh thần làm bài nghiêm túc.\n- GV nhắc HS những điều cần cố gắng thêm trong học kì II: giữ bố cục cân đối, mạnh dạn tạo đậm nhạt, giữ bài sạch.\n- GV hướng dẫn HS cách lưu giữ sản phẩm: kẹp phẳng vào bìa hồ sơ học tập, ghi rõ tên và ngày làm.\n- GV dặn dò nội dung học tập tiếp theo và đồ dùng cần chuẩn bị cho chủ đề Những kỉ niệm đẹp: ảnh tư liệu, giấy màu, màu vẽ, vật liệu làm sản phẩm kỉ niệm.","hs":"- HS lắng nghe, ghi nhớ nhận xét của GV và điều mình cần cố gắng thêm.\n- HS kẹp sản phẩm phẳng vào bìa hồ sơ học tập, ghi rõ tên và ngày làm.\n- HS nêu một việc mình sẽ làm tốt hơn trong học kì II.\n- HS ghi nhớ đồ dùng, vật liệu cần chuẩn bị cho chủ đề tiếp theo."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS mở lại thư mục ảnh sản phẩm của mình trong học kì, tự xếp theo thứ tự từ bài chưa ưng ý đến bài ưng ý nhất và chỉ ra mình đã tiến bộ ở kĩ năng nào.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chọn ba sản phẩm tiêu biểu đưa vào hồ sơ học tập và viết cho mỗi sản phẩm một dòng lí do chọn.\n⚠ (Miền 4: An toàn) HS chỉ mở thư mục mang tên mình, đặt tên tệp rõ ràng để dễ tìm; không mở, không sửa, không xoá tệp của bạn; hồ sơ học tập chỉ HS và GV cùng xem.","hs":"- HS tự sắp xếp và đánh giá được các sản phẩm của mình trong học kì.\n- HS lập được hồ sơ ba sản phẩm tiêu biểu kèm lí do chọn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Kiểm tra, đánh giá cuối học kì I"},
{"lop":4,"mon":"Mĩ thuật","tuan":18,"tiet":18,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS phân tích được nhân vật chính và bối cảnh trong một bức ảnh kỉ niệm.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu bộ ảnh kỉ niệm của lớp chụp trong năm học cùng vài ảnh tư liệu về các cách người ta lưu giữ kỉ niệm: album ảnh, sổ tay, tranh vẽ; HS nhận ra một khoảnh khắc có thể được lưu giữ bằng nhiều cách khác nhau.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn một bức ảnh kỉ niệm và chỉ ra nhân vật chính, bối cảnh và điều gì làm bức ảnh ấy đáng nhớ.\n⚠ (Miền 4: An toàn) Ảnh kỉ niệm của lớp chỉ dùng trong lớp; trước khi đưa ảnh có mặt bạn vào bài, HS phải hỏi bạn; bạn nào không muốn hình mình xuất hiện thì phải tôn trọng.","hs":"- HS phân tích được nhân vật chính và bối cảnh trong một bức ảnh kỉ niệm.\n- HS nêu được nguyên tắc hỏi ý kiến bạn trước khi dùng ảnh có mặt bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":19,"tiet":19,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS so sánh được các cách cắt khung và chọn bố cục làm nổi nhân vật chính.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS dùng chức năng cắt ảnh trong phần mềm xem ảnh, thử cắt cùng một bức ảnh kỉ niệm theo ba khung khác nhau rồi so sánh khung nào làm nhân vật chính nổi bật, khung nào làm bức ảnh rối; cắt và hoàn tác được nhiều lần nên HS thử thoải mái.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS chọn khung ưng ý nhất làm bố cục cho bài vẽ của mình và giải thích lựa chọn đó.\n⚠ (Miền 4: An toàn) Thao tác trên bản sao của ảnh và giữ nguyên tệp gốc để không làm mất ảnh kỉ niệm chung của lớp; lưu bài vào thư mục của mình.","hs":"- HS so sánh được các cách cắt khung và chọn bố cục làm nổi nhân vật chính.\n- HS giải thích được lí do chọn bố cục cho bài của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":20,"tiet":20,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện hình ảnh, hoạt động lưu giữ kỉ niệm; bố cục nhân vật và bối cảnh theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về hoạt động lưu giữ kỉ niệm của HS để trình chiếu; sản phẩm mẫu gồm một bức tranh kỉ niệm và một khung ảnh, sổ lưu niệm để phân tích trực quan; bảng tiêu chí đánh giá viết to; phiếu tự đánh giá ba mức; kẹp giấy, dây treo để trưng bày.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, ảnh tư liệu, giấy màu và vật liệu làm sản phẩm kỉ niệm; vật liệu thay thế dễ kiếm: bìa carton hộp bánh, giấy báo cũ, mặt sau tờ lịch cũ, vỏ hộp, lá cây khô ép phẳng, hột hạt, dây len, vải vụn, cúc áo cũ.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác, ảnh tư liệu và vật liệu lên bàn, kiểm tra nhanh và bổ sung cho HS còn thiếu.\n- GV tổ chức hoạt động Kể một kỉ niệm: mời 3 HS kể thật ngắn một kỉ niệm đáng nhớ ở trường và hỏi: Kỉ niệm ấy có những ai, diễn ra ở đâu?\n- GV hỏi tiếp: Nếu vẽ lại kỉ niệm đó, em sẽ chọn khoảnh khắc nào để làm hình ảnh chính?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm lưu giữ kỉ niệm.","hs":"- HS đặt bản phác, ảnh tư liệu, màu và vật liệu lên bàn, báo cáo phần còn thiếu.\n- 3 HS kể ngắn gọn một kỉ niệm, nêu rõ nhân vật và nơi diễn ra.\n- HS trả lời: em chọn lúc cả lớp cùng chụp ảnh cuối năm, lúc chúng em trồng cây ở sân trường.\n- HS lắng nghe, sẵn sàng vào bài học và bày chất liệu đã chuẩn bị."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải thể hiện được một hoạt động lưu giữ kỉ niệm, có nhóm nhân vật và bối cảnh rõ ràng.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: nhóm nhân vật chính đặt gần giữa và chiếm khoảng hai phần ba diện tích; bối cảnh vẽ đơn giản để không lấn nhân vật; dùng gam màu ấm và tươi cho không khí vui; nếu làm khung ảnh hay sổ lưu niệm thì chừa chỗ để dán ảnh và viết lời ghi nhớ.\n- GV làm mẫu chậm ở bước khó là dựng nhóm nhân vật: xếp các dáng người theo hình vòng cung hoặc so le, người trước hơi thấp, người sau cao hơn và che khuất một phần để nhóm có chiều sâu.\n- GV hỏi: Nếu vẽ các bạn đứng thẳng hàng bằng nhau thì tranh sẽ ra sao? GV chốt cách sắp xếp; nhắc an toàn khi dùng kéo, keo và giữ gìn ảnh tư liệu của gia đình.","hs":"- HS quan sát sản phẩm mẫu, chỉ ra nhóm nhân vật chính và bối cảnh trên sản phẩm.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn hình thức thể hiện.\n- HS theo dõi GV làm mẫu, nhắc lại cách xếp nhóm nhân vật so le và che khuất một phần.\n- HS trả lời: tranh sẽ cứng và đơn điệu, không thấy được không khí quây quần.\n- HS nhắc lại quy định an toàn và cách giữ gìn ảnh tư liệu."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 chuyển bố cục đã phác lên nền sản phẩm; Bước 2 dựng nhóm nhân vật chính; Bước 3 làm bối cảnh và chi tiết gợi kỉ niệm; Bước 4 thể hiện màu và đậm nhạt; Bước 5 hoàn thiện, dán ảnh hoặc viết một dòng lời ghi nhớ và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm hợp lí, an toàn; HS không có ảnh có thể vẽ chân dung nhỏ hoặc dán hình cắt từ giấy màu thay thế.\n- GV đi từng bàn hỗ trợ: chỉnh lại thế đứng cho HS vẽ nhóm nhân vật còn dàn hàng ngang, gợi ý HS làm nhanh thêm khung viền trang trí bằng lá khô, dây len, cúc áo.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, gom vật liệu thừa, cất kéo, keo và lau bàn.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách xếp nhóm nhân vật và cách trang trí viền.\n- HS thể hiện màu ấm, tạo đậm nhạt để nhóm nhân vật chính nổi lên trên bối cảnh.\n- HS dán ảnh hoặc viết một dòng lời ghi nhớ, đối chiếu bài với tiêu chí rồi đặt tên sản phẩm.\n- HS hoàn thiện, gom vật liệu thừa, cất kéo và keo đúng chỗ, lau sạch bàn."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành góc Kỉ niệm của chúng em ở lớp: treo tranh lên dây bằng kẹp giấy, đặt khung ảnh và sổ lưu niệm lên bàn kê phía dưới.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) thể hiện rõ một kỉ niệm, có nhóm nhân vật và bối cảnh; (2) bố cục cân đối, nhóm nhân vật chính nổi bật; (3) màu sắc hài hoà, có đậm nhạt, gợi được không khí vui; (4) sản phẩm sạch sẽ, hoàn chỉnh, có ý tưởng riêng.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS giữ sản phẩm ở góc lớp và chuẩn bị màu vẽ, giấy màu, lá cây, vật liệu tự nhiên cho chủ đề sau.","hs":"- HS treo hoặc đặt sản phẩm vào đúng khu trưng bày, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì nhìn bức tranh là nhớ ngay buổi trồng cây của lớp mình.\n- HS nhắc lại điều đã học và ghi nhớ vật liệu cần chuẩn bị cho chủ đề sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":21,"tiet":21,"bai":"Chủ đề 5: Những kỉ niệm đẹp (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quý thầy cô, bạn bè và những kỉ niệm tuổi học trò.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS viết được chú thích cho tác phẩm của mình trong album lớp.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, ảnh tư liệu, giấy màu, vật liệu làm sản phẩm kỉ niệm (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến những kỉ niệm đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp làm một trang album kỉ niệm gồm ảnh sản phẩm của tất cả HS, sắp xếp theo mốc thời gian trong năm học; mỗi HS viết một dòng chú thích cho tác phẩm của mình.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đọc chú thích của bạn và viết lại một kỉ niệm chung mà chú thích ấy gợi cho mình nhớ.\n⚠ (Miền 4: An toàn) Album chỉ lưu trên máy của lớp và chiếu trong buổi sinh hoạt, không đăng lên mạng xã hội khi cha mẹ các bạn chưa đồng ý; không viết chú thích trêu chọc bạn.","hs":"- HS viết được chú thích cho tác phẩm của mình trong album lớp.\n- HS phản hồi tích cực với phần chú thích của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 5, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":22,"tiet":22,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chụp và chọn được góc trường có bố cục phù hợp để vẽ.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường yêu dấu.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS dùng thiết bị của lớp chụp lại các góc của trường: cổng, hành lang, sân sau, gốc cây; sau đó xem lại trên màn hình lớn và chọn góc có bố cục đẹp nhất để vẽ, vì nhìn qua khung ảnh giúp nhận ra bố cục rõ hơn nhìn bằng mắt thường.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS giải thích vì sao góc mình chọn là đẹp: có mảng chính, có đường dẫn mắt, có khoảng trống hợp lí.\n⚠ (Miền 4: An toàn) Đi chụp theo nhóm và theo lộ trình GV giao, không leo trèo, không ra khỏi khu vực cho phép; chỉ chụp cảnh, nếu trong khung có bạn thì phải hỏi bạn trước.","hs":"- HS chụp và chọn được góc trường có bố cục phù hợp để vẽ.\n- HS giải thích được lí do chọn góc nhìn của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":23,"tiet":23,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về cây cối, con vật và cảnh quan sân trường để trình chiếu; sản phẩm mẫu và một bản phác bố cục làm dở để phân tích trực quan; một số lá cây có gân nổi và con lăn để minh hoạ kĩ thuật in lá; bảng tiêu chí đánh giá viết to.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy vẽ, giấy màu, lá cây và vật liệu tự nhiên; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, vỏ hộp, vỏ cây khô, sỏi nhỏ, hột hạt, dây len, vải vụn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, kiểm tra nhanh đồ dùng và vật liệu tự nhiên HS mang theo, xếp chung vào khay của nhóm.\n- GV tổ chức trò chơi Nhìn nhanh đoán đúng: chiếu ảnh một góc sân trường và hỏi: Trong ảnh có những cây gì, con vật gì? Hình ảnh nào em muốn đưa vào bài của mình?\n- GV hỏi tiếp: Ở sân trường mình, chỗ nào em thấy đẹp nhất và vì sao?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: tìm hiểu cách thực hiện sản phẩm về vẻ đẹp thiên nhiên nơi mái trường thân yêu.","hs":"- HS xếp vật liệu tự nhiên vào khay chung của nhóm, nêu tên từng loại đã mang.\n- HS quan sát ảnh và trả lời: có cây phượng, cây bàng, luống hoa, đàn chim sẻ và chú mèo dưới gốc cây.\n- HS nêu góc sân trường mình thấy đẹp và lí do: gốc phượng nở hoa đỏ vào mùa hè.\n- HS lắng nghe, sẵn sàng vào bài học và mở SGK Mĩ thuật 4."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- (10 phút) GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4, khai thác vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống: Bước 1 chọn góc cảnh và hình ảnh chính; Bước 2 phác mảng chính to, đặt lệch nhẹ khỏi chính giữa; Bước 3 phác mảng phụ và các lớp cảnh xa gần; Bước 4 vẽ hoặc in chi tiết cây, lá, con vật; Bước 5 thể hiện màu và đậm nhạt để mảng chính nổi lên.\n- GV làm mẫu chậm ở bước khó là bước 4 với kĩ thuật in lá cây: quét màu đều lên mặt có gân của lá, úp xuống giấy, đặt giấy lót lên trên rồi miết đều từ giữa ra ngoài, nhấc lá lên theo chiều thẳng đứng; mời 2 HS lên thao tác thử.\n- GV lưu ý kĩ thuật hay hỏng: màu loãng quá thì hình nhoè, màu đặc quá thì mất gân lá, miết không đều thì mất một góc hình; gắn vật liệu thì bôi keo mỏng ở mặt sau, vật nặng thì ấn giữ khoảng 10 giây.\n- GV hỏi: Muốn tán cây phía sau lùi ra xa thì tô màu thế nào? GV chốt và nhắc an toàn khi dùng kéo, keo, màu; nhắc HS chỉ nhặt lá rụng, không bẻ cành lá tươi trong sân trường.","hs":"- HS quan sát, phân tích các bước thực hiện và chỉ vào hình minh hoạ tương ứng trong SGK.\n- HS nêu lại 5 bước theo đúng thứ tự và ghi nhớ vào vở.\n- HS theo dõi GV làm mẫu kĩ thuật in lá; 2 HS lên thao tác thử trước lớp.\n- HS trả lời: tán cây phía sau tô nhạt hơn và bớt chi tiết thì sẽ lùi ra xa.\n- HS nhắc lại lỗi cần tránh khi in lá và quy định an toàn, bảo vệ cây xanh."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- (13 phút) GV cho HS phác nhanh ý tưởng và bố cục cho sản phẩm của mình trên giấy nháp, mỗi HS phác 2 phương án rồi chọn một phương án ưng ý nhất để phát triển.\n- GV nêu yêu cầu của bản phác: có mảng chính là cây hoặc con vật, ít nhất hai mảng phụ về cảnh quan, phân biệt được lớp cảnh gần và lớp cảnh xa, ghi chú chất liệu định dùng ở mỗi mảng.\n- GV quan sát, gợi ý điều chỉnh cho từng HS: mảng chính còn nhỏ thì phóng to, các mảng chia đều quá thì dồn lại cho có chỗ thưa chỗ dày, nhắc HS thử ướm lá lên bản phác để chọn chỗ in.\n- GV nhắc HS chuẩn bị chất liệu phù hợp và báo trước còn 2 phút để ghi tên, kẹp bản phác cùng lá cây đã chọn vào vở giữ phẳng.","hs":"- HS phác 2 phương án ý tưởng, so sánh rồi chọn một phương án ưng ý nhất.\n- HS thể hiện rõ mảng chính, mảng phụ và các lớp cảnh trên bản phác.\n- HS lựa chọn cách thể hiện, ướm thử lá cây lên bản phác để chọn chỗ in và ghi chú chất liệu.\n- HS nghe góp ý của GV, chỉnh lại bố cục rồi ghi tên và kẹp bản phác vào vở."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV cho HS dán bản phác lên bảng nhóm theo chủ đề: bảng Cây xanh sân trường, bảng Con vật quanh em, bảng Vườn hoa của lớp.\n- GV nêu tiêu chí nhận xét bản phác: (1) có mảng chính rõ, đúng hình ảnh đã chọn; (2) bố cục cân đối, phân biệt được lớp cảnh gần và xa; (3) dự kiến chất liệu hợp lí, khả thi; (4) bản phác sạch, nét gọn, có ý tưởng riêng.\n- GV cho HS tự đánh giá bản phác của mình theo 4 tiêu chí, sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào bản phác mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS ép phẳng lá cây, chuẩn bị màu vẽ, giấy vẽ, giấy màu và vật liệu tự nhiên cho tiết thực hành sau.","hs":"- HS dán bản phác lên bảng nhóm đúng chủ đề, ghi tên vào góc bài.\n- HS nghe và nhắc lại 4 tiêu chí nhận xét bản phác.\n- HS tự đánh giá bản phác của mình theo tiêu chí rồi đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn định in lá bàng làm tán cây, nhìn sẽ rất thật.\n- HS nhắc lại điều đã học và ghi nhớ cách ép lá, vật liệu cần chuẩn bị cho tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":24,"tiet":24,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện vẻ đẹp của thiên nhiên, cây cối, con vật trong môi trường sống theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về cây cối, con vật và cảnh quan sân trường để trình chiếu; sản phẩm mẫu và một bài in lá bị nhoè để HS rút kinh nghiệm; con lăn hoặc thìa nhựa để miết khi in lá, giấy lót, khăn lau; bảng tiêu chí đánh giá; phiếu tự đánh giá ba mức.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy vẽ, giấy màu, lá cây ép phẳng và vật liệu tự nhiên; vật liệu thay thế dễ kiếm: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, vỏ hộp, vỏ cây khô, sỏi nhỏ, hột hạt, dây len, vải vụn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác, lá cây đã ép và vật liệu lên bàn, kiểm tra nhanh và bổ sung cho HS còn thiếu.\n- GV chiếu một bài in lá đẹp và một bài in bị nhoè rồi hỏi: Bài nào giữ được gân lá rõ? Theo em vì sao bài kia bị nhoè?\n- GV hỏi tiếp: Trong bản phác của em, hình ảnh chính là cây gì hay con vật gì?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm theo bản phác đã chọn.","hs":"- HS đặt bản phác, lá cây ép phẳng, màu và vật liệu lên bàn, báo cáo phần còn thiếu.\n- HS quan sát và trả lời: bài thứ nhất rõ gân lá hơn; bài kia bị nhoè vì màu pha loãng quá hoặc miết mạnh tay.\n- HS chỉ ra hình ảnh chính trên bản phác của mình và nêu chất liệu định dùng.\n- HS lắng nghe, sẵn sàng vào bài học và bày chất liệu đã chuẩn bị."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải làm nổi được vẻ đẹp của cây cối, con vật trong môi trường sống quanh mái trường.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: mảng chính to, đặt lệch nhẹ khỏi chính giữa; lớp cảnh xa tô nhạt và ít chi tiết; kết hợp không quá ba loại vật liệu để bài không bị rối; giữ một khoảng trống cho tranh thoáng.\n- GV làm mẫu chậm lại kĩ thuật in lá và cách gắn vật liệu: quét màu vừa phải lên mặt có gân, úp xuống, lót giấy, miết đều từ giữa ra ngoài; keo bôi mỏng ở mặt sau vật liệu, vật nặng thì ấn giữ khoảng 10 giây.\n- GV hỏi: Nếu dán quá nhiều vật liệu lên bài thì chuyện gì xảy ra? GV chốt; nhắc an toàn khi dùng kéo, keo, màu và nhắc lót giấy báo dưới chỗ ngồi trước khi in.","hs":"- HS quan sát sản phẩm mẫu, chỉ ra mảng chính, lớp cảnh xa gần và các vật liệu đã dùng.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn không quá ba loại vật liệu.\n- HS theo dõi GV làm mẫu, nhắc lại kĩ thuật in lá và cách bôi keo gắn vật liệu.\n- HS trả lời: bài sẽ bị rối, nặng và dễ bong, không nhìn ra hình ảnh chính.\n- HS lót giấy báo dưới chỗ ngồi và nhắc lại quy định an toàn, vệ sinh."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 chuyển bố cục đã phác lên giấy chính thức; Bước 2 in hoặc vẽ các mảng lớn của lớp cảnh xa; Bước 3 làm mảng chính là cây hoặc con vật; Bước 4 gắn vật liệu tự nhiên và thêm chi tiết; Bước 5 tạo đậm nhạt, viền nét chỗ cần rõ và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên hợp lí, an toàn; HS thiếu vật liệu thiên nhiên có thể xé giấy báo cũ vò nhàu tạo chất cảm sần hoặc dán vỏ trứng vụn.\n- GV đi từng bàn hỗ trợ, làm mẫu lại thao tác miết lá cho HS in bị nhoè, gợi ý HS làm nhanh thêm chi tiết như đàn chim, ghế đá, cổng trường.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa, lau bàn và rửa tay.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách in lá và cách chọn vật liệu cho từng mảng.\n- HS in hoặc vẽ lớp cảnh xa trước, làm mảng chính sau, gắn vật liệu vừa đủ để bài không bị rối.\n- HS tạo đậm nhạt, đối chiếu bài với tiêu chí rồi đặt tên sản phẩm.\n- HS hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa, lau bàn và rửa tay."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini ở góc lớp, chia bảng nhóm theo chủ đề: bảng Cây xanh sân trường, bảng Con vật quanh em, bảng Vườn hoa của lớp.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) có hình ảnh chính rõ về cây cối hoặc con vật; (2) bố cục cân đối, phân biệt được lớp cảnh gần và xa; (3) màu sắc hài hoà, có đậm nhạt; chất liệu kết hợp hợp lí; (4) sản phẩm sạch sẽ, chắc chắn, có ý tưởng riêng.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; nhắc HS giữ gìn cây xanh sân trường và chuẩn bị màu vẽ, giấy các loại, vật liệu tái chế cho chủ đề Môi trường xanh - sạch - đẹp.","hs":"- HS dán sản phẩm lên bảng nhóm đúng chủ đề, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì gân lá in rõ làm tán cây trông rất thật.\n- HS nhắc lại điều đã học, nêu một việc mình sẽ làm để bảo vệ cây xanh và ghi nhớ vật liệu cần chuẩn bị."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":25,"tiet":25,"bai":"Chủ đề 6: Mái trường yêu dấu (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu thiên nhiên, có ý thức bảo vệ môi trường.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS đối chiếu được tranh vẽ của mình với ảnh chụp thực tế.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, giấy màu, lá cây, vật liệu tự nhiên (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường yêu dấu.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp ghép ảnh chụp các góc trường cùng tranh vẽ tương ứng thành trang trưng bày hai cột Ảnh chụp và Tranh vẽ; người xem so sánh được HS đã chọn giữ lại gì và lược bỏ gì so với thực tế.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS nhận xét theo đôi bạn: bạn đã lược bỏ chi tiết nào hợp lí, chi tiết nào tiếc vì bị bỏ mất.\n⚠ (Miền 4: An toàn) Ảnh chụp trường và tranh vẽ đều ghi tên tác giả; trang trưng bày dùng trong trường, muốn đưa lên trang thông tin của trường phải được GV và nhà trường đồng ý.","hs":"- HS đối chiếu được tranh vẽ của mình với ảnh chụp thực tế.\n- HS nhận xét được cách chọn lọc chi tiết của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 6, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":26,"tiet":26,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình).\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc và ghi được số liệu về môi trường kèm nguồn tin cậy.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình).\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem bộ ảnh chụp cùng một địa điểm trước và sau khi bị rác thải xâm chiếm, kèm số liệu về rác thải nhựa lấy từ trang của cơ quan nhà nước; ảnh đối chiếu và số liệu cho thấy vấn đề rõ hơn nhiều so với chỉ nghe kể.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS ghi lại một số liệu mình thấy ấn tượng nhất cùng tên trang đã cung cấp số liệu đó để đưa vào tranh cổ động.\n⚠ (Miền 4: An toàn) Số liệu về môi trường phải lấy từ trang của cơ quan nhà nước hoặc tổ chức có uy tín và ghi rõ nguồn; không chia sẻ lại ảnh gây sốc chưa rõ nơi chụp vì nhiều ảnh là của nơi khác hoặc đã bị chỉnh sửa.","hs":"- HS đọc và ghi được số liệu về môi trường kèm nguồn tin cậy.\n- HS nêu được vì sao phải kiểm tra nguồn trước khi tin và chia sẻ."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":27,"tiet":27,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình) thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS rút ra và vận dụng được nguyên tắc trình bày áp phích dễ đọc.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình)).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) GV cho HS so sánh hai áp phích cùng nội dung, một bản chữ nhỏ nhiều chi tiết và một bản chữ to hình đơn giản màu tương phản; HS tự rút ra nguyên tắc thiết kế áp phích rồi phác thảo bố cục chữ và hình cho sản phẩm của mình.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV nhập câu khẩu hiệu của lớp vào một công cụ tạo hình bằng trí tuệ nhân tạo cho máy sinh vài phương án bố cục; HS đối chiếu với nguyên tắc vừa rút ra và chỉ ra phương án nào máy làm được, phương án nào máy viết sai chữ tiếng Việt hoặc đặt hình lệch ý nghĩa.\n⚠ (Miền 4: An toàn) Hình do máy sinh chỉ dùng để bàn về bố cục, không đưa nguyên vào sản phẩm rồi nhận là mình vẽ; khẩu hiệu phải do HS tự nghĩ; GV là người thao tác công cụ, HS không dùng tài khoản riêng.","hs":"- HS rút ra và vận dụng được nguyên tắc trình bày áp phích dễ đọc.\n- HS chỉ ra được điểm được và chưa được của phương án do máy sinh ra."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":28,"tiet":28,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện thông điệp bảo vệ môi trường qua sản phẩm mĩ thuật (tranh cổ động, mô hình) theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về môi trường và hoạt động bảo vệ môi trường để trình chiếu; hai tranh cổ động mẫu, một tranh chữ to hình rõ và một tranh chữ nhỏ khó đọc để so sánh; mô hình mẫu làm từ vật liệu tái chế; bảng tiêu chí đánh giá; phiếu tự đánh giá ba mức.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy các loại và vật liệu tái chế (chai, lọ, bìa cứng); vật liệu thay thế dễ kiếm: giấy báo cũ, mặt sau tờ lịch cũ, vỏ hộp sữa, nắp chai, ống hút đã dùng rửa sạch, lá cây khô, dây len, vải vụn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác và vật liệu tái chế lên bàn, kiểm tra nhanh, nhắc HS vật liệu tái chế phải được rửa sạch, để khô trước khi dùng.\n- GV tổ chức trò chơi Phân loại nhanh: GV giơ lần lượt vỏ chai nhựa, vỏ hộp giấy, lá cây và hỏi: Vật này bỏ vào thùng rác nào? Có thể tái sử dụng làm gì trong bài học hôm nay?\n- GV hỏi tiếp: Thông điệp em muốn gửi qua sản phẩm của mình là gì?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm truyền thông điệp bảo vệ môi trường.","hs":"- HS đặt bản phác, màu và vật liệu tái chế đã rửa sạch lên bàn, báo cáo phần còn thiếu.\n- HS trả lời: vỏ chai nhựa và vỏ hộp giấy bỏ vào thùng rác tái chế, lá cây bỏ vào thùng rác hữu cơ.\n- HS nêu cách tái sử dụng: chai nhựa cắt làm chậu cây, vỏ hộp làm thùng rác mô hình, nắp chai làm bánh xe.\n- HS nêu thông điệp của mình: hãy trồng thêm cây xanh, không xả rác bừa bãi, hãy phân loại rác.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm phải truyền được thông điệp bảo vệ môi trường một cách rõ ràng, người xem nhìn là hiểu ngay.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: hình chính to, đặt ở chỗ dễ thấy và chiếm khoảng hai phần ba diện tích; chữ ít, to, nét đều, đặt ở khoảng trống chứ không đè lên hình; màu tương phản mạnh như xanh lá với vàng, xanh lam với trắng để nhìn từ xa vẫn rõ.\n- GV chiếu hai tranh cổ động và hỏi: Tranh nào đọc được thông điệp từ cuối lớp? Vì sao tranh kia khó đọc? GV chốt và làm mẫu chậm cách kẻ chữ: kẻ hai đường ngang giới hạn chiều cao chữ, viết nhẹ bằng bút chì rồi mới tô đậm.\n- GV lưu ý an toàn khi làm mô hình: cắt chai nhựa phần cứng do GV làm giúp, HS chỉ dùng kéo cắt giấy và bìa mỏng; băng dính che mép cắt sắc; rửa tay sau khi làm.","hs":"- HS quan sát sản phẩm mẫu, chỉ ra hình chính và vị trí đặt chữ trên tranh cổ động.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn hình thức tranh cổ động hoặc mô hình.\n- HS trả lời: tranh thứ nhất đọc được từ xa vì chữ to và màu tương phản; tranh kia chữ nhỏ và trùng màu nền.\n- HS theo dõi GV làm mẫu cách kẻ chữ và nhắc lại các bước kẻ chữ cho đều.\n- HS nhắc lại quy định an toàn khi cắt chai nhựa, bìa cứng và giữ vệ sinh."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 chốt thông điệp thật ngắn; Bước 2 phác bố cục, xác định chỗ đặt hình chính và chỗ đặt chữ; Bước 3 dựng hình chính; Bước 4 thể hiện màu tương phản và tạo đậm nhạt; Bước 5 kẻ chữ, hoàn thiện và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) hợp lí, an toàn; nhóm làm mô hình thì phân công rõ ai cắt, ai dán, ai kẻ chữ, ai trang trí.\n- GV đi từng bàn hỗ trợ: cắt giúp phần chai nhựa cứng, chỉnh lại chữ cho HS kẻ bị xiêu, gợi ý nhóm làm nhanh thêm chi tiết như thùng phân loại rác, bồn cây, dòng sông sạch.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, gom vật liệu thừa vào thùng phân loại, cất kéo, keo, lau bàn và rửa tay.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm, nhận và hoàn thành đúng phần việc được phân công.\n- HS dựng hình chính to rõ, dùng màu tương phản và kẻ chữ ngắn gọn cho thông điệp dễ đọc.\n- HS đối chiếu bài với tiêu chí, chỉnh sửa chỗ chưa đạt rồi đặt tên sản phẩm.\n- HS hoàn thiện, gom vật liệu thừa vào thùng phân loại, cất kéo và keo, lau bàn và rửa tay."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành góc truyền thông của lớp: treo tranh cổ động lên bảng nhóm theo thông điệp, mô hình đặt trên bàn kê phía dưới, mỗi sản phẩm có mẩu giấy ghi tên nhóm.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) thông điệp rõ ràng, người xem hiểu ngay; (2) bố cục cân đối, hình chính nổi bật, chữ đặt hợp lí; (3) màu sắc tương phản, có đậm nhạt, nhìn rõ từ xa; (4) sản phẩm chắc chắn, sạch sẽ, tận dụng tốt vật liệu tái chế.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; đề nghị treo sản phẩm ở hành lang để tuyên truyền cho toàn trường và dặn HS chuẩn bị màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình cho chủ đề Quê hương thanh bình.","hs":"- HS treo hoặc đặt sản phẩm vào đúng khu trưng bày, ghi tên nhóm và thông điệp.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì chữ to màu vàng trên nền xanh, đứng cuối lớp vẫn đọc được.\n- HS nhắc lại điều đã học, nêu một việc mình sẽ làm để giữ môi trường và ghi nhớ vật liệu cần chuẩn bị."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":29,"tiet":29,"bai":"Chủ đề 7: Môi trường xanh - sạch - đẹp (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- có trách nhiệm giữ gìn môi trường xanh - sạch - đẹp.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.3 CB2a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS ghi đủ nguồn tư liệu và tên tác giả trên sản phẩm chung.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy các loại, vật liệu tái chế (chai, lọ, bìa cứng) (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến môi trường xanh - sạch - đẹp.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Lớp lập trang tuyên truyền Môi trường xanh sạch đẹp gồm tranh cổ động của HS kèm khẩu hiệu, gửi tới các lớp trong trường qua màn hình sinh hoạt dưới cờ.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS ghi ở cuối trang nguồn của mọi số liệu và hình ảnh tham khảo đã sử dụng, ghi tên tác giả cho từng bức tranh.\n⚠ (Miền 4: An toàn) Thông điệp tuyên truyền phải đúng sự thật, không phóng đại số liệu để gây chú ý; chỉ chia sẻ trong phạm vi nhà trường, muốn đăng rộng hơn phải được nhà trường cho phép.","hs":"- HS đóng góp tranh và khẩu hiệu cho trang tuyên truyền của lớp.\n- HS ghi đủ nguồn tư liệu và tên tác giả trên sản phẩm chung."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 7, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":30,"tiet":30,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 1 - Quan sát, nhận biết)","yccd":"1. Năng lực mĩ thuật\n- Quan sát, nhận biết được hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D.\n- Nêu được cảm nhận ban đầu về đối tượng thẩm mĩ của chủ đề.\n- Có ý thức khai thác hình ảnh, chất liệu để chuẩn bị cho thực hành sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS so sánh được cách thể hiện sự thanh bình ở các vùng miền.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (quan sát, nhận biết).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Quan sát, nhận biết","gv":"- GV cho HS quan sát hình minh hoạ trong SGK Mĩ thuật 4 và tư liệu GV chuẩn bị thêm về hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D.\n- GV đặt câu hỏi gợi mở để HS nhận ra hình ảnh, chất liệu, cách thể hiện đặc trưng của chủ đề.\n- GV tóm tắt, bổ sung, khắc sâu nội dung Em có biết trong SGK.","hs":"- HS quan sát hình, tư liệu và trả lời câu hỏi.\n- HS nêu hiểu biết, cảm nhận ban đầu về chủ đề.\n- HS lắng nghe, ghi nhớ."},{"ten":"3. Luyện tập - Chia sẻ hiểu biết","gv":"- GV cho HS kể thêm những hình ảnh, tác phẩm cùng chủ đề mà em biết.\n- GV định hướng HS lựa chọn hình ảnh sẽ khai thác cho phần thực hành ở tiết sau.","hs":"- HS chia sẻ trước lớp.\n- HS lựa chọn ý tưởng, hình ảnh cho sản phẩm của mình."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (quan sát, nhận biết).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS xem bộ tranh và ảnh về cuộc sống làng quê ở các vùng miền, chú ý cách các tác giả chọn khoảnh khắc yên bình: buổi chiều thả diều, phiên chợ sớm, con đò qua sông; mỗi tác phẩm đều có ghi tên tác giả.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) HS chọn hai tác phẩm khác vùng miền và ghi vào phiếu điểm giống nhau về cảm xúc, điểm khác nhau về cảnh vật.\n⚠ (Miền 4: An toàn) Khi đưa ảnh tham khảo vào phiếu tư liệu, HS ghi tên tác giả và nơi lấy ảnh; không cắt bỏ chữ kí, tên tác giả trên tranh của người khác.","hs":"- HS so sánh được cách thể hiện sự thanh bình ở các vùng miền.\n- HS ghi đúng tên tác giả cho tranh, ảnh mình tham khảo."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 1 - Quan sát, nhận biết"},
{"lop":4,"mon":"Mĩ thuật","tuan":31,"tiet":31,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 2 - Cách thực hiện sản phẩm)","yccd":"1. Năng lực mĩ thuật\n- Nêu được các bước cơ bản để thể hiện hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D thành sản phẩm mĩ thuật.\n- Lựa chọn được hình ảnh, chất liệu, cách thể hiện phù hợp với khả năng.\n- Biết vận dụng yếu tố và nguyên lí tạo hình đã học vào sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 5.2 CB2b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS lấy được bảng màu chủ đạo từ một bức ảnh và đối chiếu với màu vẽ thật.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (tìm hiểu cách thực hiện).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Cách thực hiện","gv":"- GV hướng dẫn HS phân tích các bước thực hiện sản phẩm trong SGK Mĩ thuật 4 (khai thác hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D).\n- GV làm mẫu hoặc mời HS lên thao tác thử một số bước; lưu ý cách chọn hình ảnh, chất liệu phù hợp.","hs":"- HS quan sát, phân tích các bước thực hiện.\n- HS nêu lại các bước và ghi nhớ."},{"ten":"3. Luyện tập - Thử phác ý tưởng","gv":"- GV cho HS phác nhanh ý tưởng, bố cục cho sản phẩm của mình.\n- GV quan sát, gợi ý điều chỉnh để HS chuẩn bị tốt cho tiết thực hành.","hs":"- HS phác ý tưởng, lựa chọn cách thể hiện.\n- HS chuẩn bị chất liệu phù hợp."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (tìm hiểu cách thực hiện).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS dùng công cụ chọn màu trong phần mềm xem ảnh để lấy ra bảng năm màu chủ đạo của một bức ảnh làng quê mình thích, rồi đối chiếu với hộp màu của mình xem pha được những màu nào.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS lập bảng màu cho bài của mình dựa trên kết quả vừa lấy và thử màu ra giấy nháp trước khi vẽ.\n⚠ (Miền 4: An toàn) HS thao tác trên máy của lớp, thoát phần mềm và trả máy đúng chỗ sau khi dùng; màu trên màn hình sáng hơn màu bột trên giấy nên phải thử ra giấy nháp, không tin hoàn toàn vào màu hiển thị.","hs":"- HS lấy được bảng màu chủ đạo từ một bức ảnh và đối chiếu với màu vẽ thật.\n- HS lập được bảng màu cho bài vẽ của mình."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 2 - Cách thực hiện sản phẩm"},
{"lop":4,"mon":"Mĩ thuật","tuan":32,"tiet":32,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 3 - Thực hành, sáng tạo)","yccd":"1. Năng lực mĩ thuật\n- Tạo được sản phẩm mĩ thuật thể hiện hình ảnh cuộc sống yên bình nơi quê hương qua bố cục tranh, sản phẩm 3D theo ý thích.\n- Vận dụng được hình, mảng, màu sắc, đậm nhạt để làm rõ nội dung.\n- Bước đầu thể hiện được sự sáng tạo trong sản phẩm.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.","dodung":"- GV: SGK, SGV Mĩ thuật 4; hình ảnh, clip về cuộc sống yên bình nơi làng quê để trình chiếu; sản phẩm mẫu gồm một bức tranh và một mô hình 3D để phân tích trực quan; bảng nặn, dao nhựa, tăm tre; bảng tiêu chí đánh giá viết to; phiếu tự đánh giá ba mức; đế bìa để đặt mô hình.\n- HS: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán. Vật liệu chính là màu vẽ, giấy vẽ, đất nặn và vật liệu tạo mô hình; vật liệu thay thế dễ kiếm: đất sét địa phương, giấy báo cũ vò chặt bọc hồ, bìa carton, vỏ hộp sữa làm nhà, ống hút làm cột, lá cây khô làm mái, hột hạt, dây len, vải vụn.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, cho HS đặt bản phác, đất nặn và vật liệu lên bàn, kiểm tra nhanh và bổ sung cho HS còn thiếu.\n- GV chiếu một đoạn clip ngắn về làng quê buổi chiều và hỏi: Cảnh trong clip gợi cho em cảm giác gì? Những hình ảnh nào làm em thấy yên bình?\n- GV hỏi tiếp: Trong bản phác của em, hình ảnh nào nói lên sự thanh bình của quê hương?\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học: thực hành, sáng tạo sản phẩm về quê hương thanh bình.","hs":"- HS đặt bản phác, màu, đất nặn và vật liệu lên bàn, báo cáo phần còn thiếu.\n- HS xem clip và trả lời: cảm giác yên ả, dễ chịu; nhờ hình ảnh cánh đồng, đàn trâu về chuồng, khói bếp, dòng sông.\n- HS chỉ ra hình ảnh nói lên sự thanh bình trong bản phác của mình.\n- HS lắng nghe, sẵn sàng vào bài học và bày chất liệu đã chuẩn bị."},{"ten":"2. Khám phá - Nhắc lại yêu cầu","gv":"- (7 phút) GV cho HS xem lại sản phẩm mẫu và nhắc lại yêu cầu của chủ đề trong SGK Mĩ thuật 4: sản phẩm có thể là tranh hoặc mô hình 3D nhưng phải gợi được cuộc sống yên bình nơi quê hương.\n- GV lưu ý HS về bố cục, màu sắc, chất liệu trước khi thực hành: với tranh thì chia ba lớp cảnh, mảng chính to đặt lệch nhẹ khỏi chính giữa, dùng gam màu dịu như xanh lá, vàng nhạt, nâu nhạt; với mô hình thì bố trí trên một đế bìa, có chỗ cao chỗ thấp, hình chính đặt phía trước và cao hơn.\n- GV làm mẫu chậm ở bước khó của mô hình: nặn khối nhà, cây, con vật theo khối cơ bản trước, miết kĩ chỗ nối, cắm tăm tre làm trụ cho chi tiết nhỏ, sau đó gắn xuống đế bằng một lớp keo dày.\n- GV hỏi: Nếu các khối trên mô hình cao bằng nhau và xếp thẳng hàng thì sao? GV chốt; nhắc an toàn khi dùng kéo, keo, đất nặn, không đưa đất lên miệng và rửa tay sau khi thực hành.","hs":"- HS quan sát sản phẩm mẫu, so sánh cách sắp xếp của bức tranh và của mô hình 3D.\n- HS nhớ lại yêu cầu, hình dung sản phẩm sẽ làm và chọn hình thức phù hợp với khả năng.\n- HS theo dõi GV làm mẫu, nhắc lại cách nặn khối, miết chỗ nối và gắn xuống đế.\n- HS trả lời: mô hình sẽ đơn điệu, không có chiều sâu nên phải làm cao thấp và so le.\n- HS nhắc lại quy định an toàn và vệ sinh khi thực hành."},{"ten":"3. Luyện tập - Thực hành, sáng tạo","gv":"- (16 phút) GV tổ chức cho HS thực hành cá nhân hoặc nhóm 2 đến 4 HS theo trình tự: Bước 1 chuyển bố cục đã phác lên giấy hoặc lên đế mô hình; Bước 2 dựng hình chính là nhà, cây, con vật hoặc nhóm người; Bước 3 làm các mảng phụ và lớp cảnh xa; Bước 4 thể hiện màu và đậm nhạt; Bước 5 hoàn thiện chi tiết và đặt tên sản phẩm.\n- GV theo dõi, hỗ trợ, khuyến khích HS sáng tạo và sử dụng màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình hợp lí, an toàn; nhóm thiếu đất nặn thì dùng giấy báo cũ vò chặt bọc hồ, vỏ hộp sữa làm nhà, lá cây khô làm mái.\n- GV đi từng bàn hỗ trợ: làm mẫu lại chỗ nối khối cho HS nặn bị rơi chi tiết, nhắc HS vẽ tranh chờ mảng cạnh khô mới tô tiếp để tránh loang màu.\n- GV nhắc HS bám tiêu chí khi làm và báo trước còn 3 phút để hoàn thiện, thấm khô bài, lau bảng nặn, gom vật liệu thừa, lau bàn và rửa tay.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng của mình, làm lần lượt 5 bước đã thống nhất.\n- HS trao đổi, giúp đỡ nhau trong nhóm về cách bố trí cao thấp và cách phối màu dịu.\n- HS dựng hình chính trước, mảng phụ và lớp cảnh xa sau, tạo đậm nhạt cho sản phẩm có chiều sâu.\n- HS đối chiếu bài với tiêu chí, hoàn thiện chi tiết rồi đặt tên sản phẩm.\n- HS hoàn thiện, thấm khô bài, lau bảng nặn, gom vật liệu thừa, lau bàn và rửa tay."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- (8 phút) GV tổ chức trưng bày thành phòng tranh mini và triển lãm mô hình ở góc lớp: tranh dán lên bảng nhóm theo chủ đề, mô hình đặt trên bàn kê phía dưới cho HS xem được từ nhiều phía.\n- GV nêu tiêu chí đánh giá sản phẩm: (1) có hình ảnh chính rõ, gợi được cuộc sống yên bình nơi quê hương; (2) bố cục cân đối, có lớp trước lớp sau hoặc chỗ cao chỗ thấp; (3) màu sắc hài hoà, dịu, có đậm nhạt; (4) sản phẩm chắc chắn, sạch sẽ, có ý tưởng riêng.\n- GV phát phiếu, cho HS tự đánh giá sản phẩm của mình theo 4 tiêu chí ở ba mức tốt, đạt, cần cố gắng; sau đó đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì...\n- GV cùng HS hệ thống lại nội dung tiết học, nhận xét, tuyên dương; dặn HS giữ sản phẩm và chuẩn bị giấy vẽ, màu vẽ, chất liệu quen dùng cho tiết kiểm tra cuối học kì II.","hs":"- HS dán tranh hoặc đặt mô hình vào đúng khu trưng bày, ghi tên mình và tên sản phẩm.\n- HS nghe và nhắc lại 4 tiêu chí đánh giá sản phẩm.\n- HS tự đánh giá bài của mình vào phiếu theo ba mức, sau đó đánh giá chéo bài của bạn trong nhóm.\n- HS đi xem, dán sao và nói: Mình thích bài này vì mái nhà và luỹ tre làm em nhớ đến làng mình.\n- HS nhắc lại điều đã học và ghi nhớ đồ dùng cần chuẩn bị cho tiết sau."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 3 - Thực hành, sáng tạo"},
{"lop":4,"mon":"Mĩ thuật","tuan":33,"tiet":33,"bai":"Chủ đề 8: Quê hương thanh bình (Tiết 4 - Trưng bày, thảo luận và vận dụng)","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu và nêu được cảm nhận về sản phẩm của mình, của bạn.\n- Nhận xét, đánh giá được sản phẩm dựa trên gợi ý.\n- Vận dụng được kiến thức, kĩ năng của chủ đề vào một sản phẩm gắn với cuộc sống.\n2. Năng lực chung\n- Tự chủ và tự học: chủ động chuẩn bị đồ dùng, quan sát và thực hiện nhiệm vụ học tập.\n- Giao tiếp và hợp tác: trao đổi, chia sẻ trong nhóm; giới thiệu sản phẩm trước lớp.\n- Giải quyết vấn đề và sáng tạo: lựa chọn cách thể hiện phù hợp, tạo sản phẩm theo ý tưởng riêng.\n3. Phẩm chất\n- yêu quê hương, đất nước, trân trọng cuộc sống hoà bình.\n- Chăm chỉ, có ý thức hoàn thành nhiệm vụ học tập và giữ vệ sinh khi thực hành.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS viết được phần giới thiệu ngắn cho tranh của mình.","dodung":"- Giáo viên: SGK, SGV Mĩ thuật 4; một số hình ảnh, clip minh hoạ chủ đề để trình chiếu; sản phẩm mĩ thuật mẫu; thiết bị trình chiếu học liệu số.\n- Học sinh: SGK Mĩ thuật 4, Vở bài tập Mĩ thuật 4; đồ dùng học tập: bút chì, tẩy, màu vẽ, giấy vẽ, giấy màu, kéo, keo dán; màu vẽ, giấy vẽ, đất nặn, vật liệu tạo mô hình (tuỳ điều kiện thực tế ở địa phương).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, tổ chức trò chơi hoặc hoạt động khởi động nhẹ nhàng liên quan đến quê hương thanh bình.\n- GV nhận xét, tuyên dương và dẫn dắt vào nội dung tiết học (trưng bày, thảo luận, vận dụng).","hs":"- HS tham gia khởi động vui vẻ.\n- HS lắng nghe, sẵn sàng vào bài học."},{"ten":"2. Khám phá - Trưng bày, thảo luận","gv":"- GV tổ chức cho HS trưng bày sản phẩm đã hoàn thành.\n- GV nêu câu hỏi gợi ý (SGK Mĩ thuật 4) để HS giới thiệu, nhận xét sản phẩm của mình và của bạn.","hs":"- HS trưng bày, giới thiệu sản phẩm.\n- HS nhận xét, chia sẻ cảm nhận về sản phẩm của bạn."},{"ten":"3. Luyện tập - Vận dụng","gv":"- GV gợi ý HS vận dụng kiến thức, kĩ năng của chủ đề để tạo một sản phẩm gắn với cuộc sống (trang trí góc học tập, làm quà tặng, tuyên truyền...).\n- GV liên hệ ý nghĩa của chủ đề với cuộc sống của HS.","hs":"- HS nêu ý tưởng vận dụng.\n- HS thực hiện hoặc dự kiến thực hiện sản phẩm vận dụng."},{"ten":"4. Vận dụng - Củng cố, dặn dò","gv":"- GV cùng HS hệ thống lại nội dung tiết học (trưng bày, thảo luận, vận dụng).\n- GV nhận xét tiết học, tuyên dương; dặn HS chuẩn bị đồ dùng cho tiết sau.","hs":"- HS nhắc lại điều đã học.\n- HS lắng nghe, ghi nhớ và chuẩn bị bài sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Lớp làm trang trưng bày Quê hương thanh bình xếp tranh theo vùng miền; mỗi HS viết ba dòng giới thiệu gồm tên tranh, nơi được vẽ và cảm xúc mình muốn gửi gắm.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đọc phần giới thiệu của bạn rồi viết một câu phản hồi chân thành, tránh nhận xét chung chung kiểu đẹp lắm.\n⚠ (Miền 4: An toàn) Trang trưng bày ghi tên tác giả từng tranh và nguồn ảnh tham khảo; chia sẻ trong lớp và với cha mẹ, không đăng công khai khi chưa được đồng ý.","hs":"- HS viết được phần giới thiệu ngắn cho tranh của mình.\n- HS viết được phản hồi cụ thể cho tác phẩm của bạn."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Chủ đề 8, Tiết 4 - Trưng bày, thảo luận và vận dụng"},
{"lop":4,"mon":"Mĩ thuật","tuan":34,"tiet":34,"bai":"Kiểm tra, đánh giá cuối học kì II","yccd":"1. Năng lực mĩ thuật\n- Vận dụng kiến thức, kĩ năng đã học trong học kì để hoàn thành một sản phẩm mĩ thuật theo yêu cầu.\n- Thể hiện được yếu tố, nguyên lí tạo hình (hình, mảng, màu sắc, đậm nhạt) phù hợp nội dung.\n- Giới thiệu và nêu được cảm nhận về sản phẩm của mình.\n2. Năng lực chung\n- Tự chủ và tự học; giải quyết vấn đề và sáng tạo khi hoàn thành sản phẩm.\n3. Phẩm chất\n- Chăm chỉ, trung thực, có trách nhiệm; tự tin thể hiện sản phẩm của mình.","dodung":"- GV: đề kiểm tra hoặc yêu cầu thực hành, bảng tiêu chí đánh giá viết to treo trước lớp; bảng hệ thống các chủ đề đã học trong học kì II; phiếu tự đánh giá ba mức tốt, đạt, cần cố gắng; sao giấy để HS bình chọn; sổ theo dõi sự tiến bộ của HS; thiết bị trình chiếu học liệu số.\n- HS: đồ dùng học tập môn Mĩ thuật, giấy vẽ, màu vẽ, chất liệu đã chuẩn bị. Vật liệu thay thế dễ kiếm khi thiếu đồ dùng: mặt sau tờ lịch cũ, giấy báo cũ, bìa carton, giấy màu, vỏ hộp, nắp chai, lá cây khô, hột hạt, dây len, vải vụn, đất sét địa phương.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV ổn định lớp, nêu mục đích tiết kiểm tra cuối học kì II: đánh giá sự tiến bộ của mỗi HS qua một sản phẩm mĩ thuật hoàn chỉnh, khuyến khích HS thể hiện ý tưởng riêng.\n- GV cùng HS nhắc lại nhanh các chủ đề đã học trong học kì bằng sơ đồ nhánh và hỏi: Chủ đề nào em thấy mình tiến bộ nhất? Kĩ năng nào em đã làm tốt hơn so với đầu năm?\n- GV công bố yêu cầu và tiêu chí đánh giá sản phẩm, treo bảng tiêu chí trước lớp cho HS đọc và hỏi lại chỗ chưa rõ.\n- GV nhắc HS chọn nội dung và chất liệu vừa sức để hoàn thành trong tiết học; nhắc an toàn khi dùng kéo, keo, màu và giữ vệ sinh chỗ ngồi.","hs":"- HS lắng nghe, nắm yêu cầu và tiêu chí; đọc lại bảng tiêu chí treo trước lớp.\n- HS nhắc lại tên các chủ đề đã học trong học kì và kĩ năng chính của từng chủ đề.\n- HS trả lời: em tiến bộ nhất ở chủ đề Môi trường xanh - sạch - đẹp vì em đã biết kẻ chữ đều và chọn màu tương phản.\n- HS hỏi lại chỗ chưa rõ và bày đồ dùng, chất liệu lên bàn."},{"ten":"2. Thực hành kiểm tra","gv":"- (17 phút) GV tổ chức cho HS làm bài thực hành: mỗi HS tạo một sản phẩm mĩ thuật theo một chủ đề đã học trong học kì, làm theo trình tự Bước 1 chọn nội dung và chất liệu; Bước 2 phác bố cục, xác định mảng chính; Bước 3 dựng hình chi tiết; Bước 4 thể hiện màu và đậm nhạt; Bước 5 hoàn thiện, đặt tên và ghi tên mình.\n- GV bao quát lớp, hỗ trợ khi cần nhưng không làm thay, bảo đảm HS làm bài độc lập; nhắc HS bám bốn tiêu chí đã công bố và mạnh dạn thể hiện ý tưởng riêng.\n- GV gợi ý cho HS thiếu chất liệu: dùng mặt sau tờ lịch cũ thay giấy vẽ, xé dán giấy màu, dán lá cây khô, hột hạt hoặc nặn bằng đất sét địa phương.\n- GV báo trước còn 3 phút để hoàn thiện, thấm khô bài, rửa cọ, gom vật liệu thừa, lau bàn và rửa tay.","hs":"- HS thực hành tạo sản phẩm theo yêu cầu, làm lần lượt 5 bước đã nêu.\n- HS vận dụng kiến thức, kĩ năng đã học về hình, mảng, màu sắc, đậm nhạt vào bài của mình.\n- HS làm bài độc lập, tự giải quyết khó khăn trước khi nhờ GV hỗ trợ.\n- HS đối chiếu bài với tiêu chí, chỉnh sửa rồi đặt tên sản phẩm và ghi tên mình.\n- HS hoàn thiện, thấm khô bài, gom vật liệu thừa, lau bàn và rửa tay."},{"ten":"3. Trưng bày, đánh giá","gv":"- (8 phút) GV tổ chức cho HS trưng bày thành phòng tranh mini cuối năm ở góc lớp, chia bảng nhóm theo các chủ đề đã học; sản phẩm 3D đặt trên bàn kê phía dưới cho HS xem được nhiều phía.\n- GV nêu lại tiêu chí đánh giá: (1) có hình ảnh chính rõ, đúng chủ đề đã chọn; (2) bố cục cân đối, mảng chính phụ hợp lí; (3) màu sắc hài hoà, có đậm nhạt làm rõ nội dung; (4) sản phẩm hoàn chỉnh, sạch sẽ, có ý tưởng riêng.\n- GV phát phiếu cho HS tự đánh giá theo ba mức tốt, đạt, cần cố gắng; sau đó cho HS đổi bài trong nhóm để đánh giá chéo, mỗi bạn nêu một điểm mạnh và một điểm nên chỉnh.\n- GV cho HS đi xem, dán sao vào sản phẩm mình thích và nói theo mẫu: Mình thích bài này vì... GV nhận xét, đánh giá theo tiêu chí và ghi nhận sự tiến bộ của từng HS vào sổ theo dõi.","hs":"- HS trưng bày sản phẩm vào đúng khu, giới thiệu ngắn về tên sản phẩm, nội dung và chất liệu đã dùng.\n- HS nêu cảm nhận về sản phẩm của mình: em thích nhất mảng màu nào và vì sao.\n- HS tự đánh giá sản phẩm của mình vào phiếu theo bốn tiêu chí ở ba mức.\n- HS đổi bài trong nhóm, nhận xét sản phẩm của bạn, nêu một điểm mạnh và một điểm nên chỉnh.\n- HS đi xem, dán sao và nói: Mình thích bài này vì bạn đã tiến bộ rất nhiều so với đầu năm."},{"ten":"4. Vận dụng - Dặn dò","gv":"- (6 phút) GV tổng kết tiết kiểm tra, nêu tên những HS có tiến bộ rõ rệt trong cả năm học và tuyên dương tinh thần làm bài nghiêm túc, sáng tạo của cả lớp.\n- GV cùng HS nhìn lại chặng đường cả năm bằng câu hỏi: Kĩ năng mĩ thuật nào em thấy mình tiến bộ nhất? Em muốn học thêm điều gì ở lớp trên?\n- GV hướng dẫn HS lưu giữ sản phẩm: kẹp phẳng vào bìa hồ sơ học tập, ghi rõ tên, chủ đề và ngày làm; chọn hai sản phẩm tâm đắc nhất để mang tới tiết trưng bày cuối năm.\n- GV dặn dò nội dung học tập tiếp theo và gợi ý HS trong hè có thể vẽ, nặn, làm đồ thủ công từ vật liệu tái sử dụng ở nhà để giữ thói quen sáng tạo.","hs":"- HS lắng nghe, ghi nhớ nhận xét của GV và điều mình cần cố gắng thêm.\n- HS trả lời: em tiến bộ nhất ở kĩ năng tạo đậm nhạt và sắp xếp bố cục cho cân đối.\n- HS kẹp sản phẩm phẳng vào bìa hồ sơ học tập, ghi rõ tên, chủ đề và ngày làm.\n- HS chọn hai sản phẩm tâm đắc nhất và ghi nhớ chuẩn bị cho tiết trưng bày cuối năm."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Kiểm tra, đánh giá cuối học kì II"},
{"lop":4,"mon":"Mĩ thuật","tuan":35,"tiet":35,"bai":"Trưng bày sản phẩm và tổng kết năm học","yccd":"1. Năng lực mĩ thuật\n- Trưng bày, giới thiệu được các sản phẩm mĩ thuật tiêu biểu đã làm trong năm học.\n- Nêu được cảm nhận, nhận xét về sản phẩm của mình và của bạn.\n- Nhận ra sự tiến bộ của bản thân qua các sản phẩm mĩ thuật.\n2. Năng lực chung\n- Giao tiếp và hợp tác: cùng nhau tổ chức, sắp xếp không gian trưng bày.\n- Tự chủ và tự học: tự lựa chọn, giới thiệu sản phẩm của mình.\n3. Phẩm chất\n- Yêu thích môn học; tự tin, trân trọng thành quả của mình và của bạn.\n4. Tích hợp\n- Năng lực số 3.1 CB2a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS tham gia dựng trang triển lãm số và viết đúng chú thích cho sản phẩm.","dodung":"- Giáo viên: không gian trưng bày, bảng hoặc giá treo sản phẩm; thiết bị trình chiếu học liệu số.\n- Học sinh: các sản phẩm mĩ thuật đã làm trong năm học; đồ dùng để trưng bày.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tạo không khí vui tươi cho tiết tổng kết cuối năm.\n- GV giới thiệu ý nghĩa của buổi trưng bày sản phẩm mĩ thuật.","hs":"- HS hào hứng tham gia.\n- HS lắng nghe."},{"ten":"2. Khám phá - Chuẩn bị trưng bày","gv":"- GV hướng dẫn HS lựa chọn, sắp xếp các sản phẩm tiêu biểu của mình theo chủ đề hoặc nhóm.\n- GV gợi ý cách bố trí không gian trưng bày đẹp, khoa học.","hs":"- HS lựa chọn sản phẩm, sắp xếp theo hướng dẫn.\n- HS cùng nhau trang trí khu trưng bày."},{"ten":"3. Luyện tập - Trưng bày, giới thiệu","gv":"- GV tổ chức cho HS trưng bày và giới thiệu sản phẩm trước lớp.\n- GV khuyến khích HS nêu cảm nhận, nhận xét về sản phẩm của bạn.","hs":"- HS giới thiệu sản phẩm của mình.\n- HS quan sát, nhận xét sản phẩm của bạn."},{"ten":"4. Vận dụng - Tổng kết năm học","gv":"- GV cùng HS nhìn lại chặng đường học tập môn Mĩ thuật trong năm.\n- GV tuyên dương, động viên; gợi mở việc tiếp tục sáng tạo trong dịp hè.","hs":"- HS chia sẻ điều tâm đắc nhất trong năm học.\n- HS nêu mong muốn tiếp tục học và sáng tạo mĩ thuật."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) HS cùng GV dựng một trang triển lãm số cuối năm chia theo tám chủ đề đã học, mỗi chủ đề chọn vài sản phẩm tiêu biểu; HS phụ trách phần chú thích gồm tên chủ đề, tên tác giả và chất liệu.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS đóng vai người thuyết minh, giới thiệu một chủ đề trong triển lãm cho khách tham quan là các bạn lớp khác và cha mẹ.\n⚠ (Miền 4: An toàn) Triển lãm ghi đủ tên tác giả cho từng sản phẩm và ghi nguồn cho mọi hình ảnh tham khảo; chỉ chiếu trong buổi tổng kết ở trường, đưa lên mạng phải được nhà trường và cha mẹ đồng ý.","hs":"- HS tham gia dựng trang triển lãm số và viết đúng chú thích cho sản phẩm.\n- HS thuyết minh được một chủ đề của triển lãm trước người xem."}],"status":"checked","source":"KHBD Mĩ thuật 4 KNTT (Bút Xanh) - Trưng bày, tổng kết cuối năm"}
];
